INSERT INTO rebalance_input (id, old_options, new_options) VALUES
  ('ca_064', $opt$[{"text":"Reviewing security level periodically","isCorrect":true,"rationale":"Reclassification periodically reviews inmate security level based on behavior and progress.","is_correct":true},{"text":"One-time classification","isCorrect":false,"rationale":"'One-time classification' is incorrect. The correct answer is 'Reviewing security level periodically'. Reclassification periodically reviews inmate security level based on behavior and progress. Review: Inmate Classification.","is_correct":false},{"text":"No review","isCorrect":false,"rationale":"'No review' is incorrect. The correct answer is 'Reviewing security level periodically'. Reclassification periodically reviews inmate security level based on behavior and progress. Review: Inmate Classification.","is_correct":false},{"text":"Only at release","isCorrect":false,"rationale":"'Only at release' is incorrect. The correct answer is 'Reviewing security level periodically'. Reclassification periodically reviews inmate security level based on behavior and progress. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Reviewing security level periodically","isCorrect":true,"rationale":"Reclassification periodically reviews inmate security level based on behavior and progress.","is_correct":true},{"text":"Assigning the security level once upon admission","is_correct":false,"rationale":"That is initial classification at reception. Reclassification is the periodic review that follows it."},{"text":"Transferring an inmate to another facility","is_correct":false,"rationale":"A transfer may follow a review, but moving an inmate is not the same as reassessing their classification."},{"text":"Grouping inmates by the crime committed","is_correct":false,"rationale":"Classification weighs risk and needs, not only the offense; reclassification means reviewing that level again over time."}]$opt$::jsonb),
  ('ca_100', $opt$[{"text":"Decentralized housing with dedicated staff","isCorrect":true,"rationale":"Unit management assigns dedicated staff to smaller inmate groups.","is_correct":true},{"text":"Centralized control","isCorrect":false,"rationale":"'Centralized control' is incorrect. The correct answer is 'Decentralized housing with dedicated staff'. Unit management assigns dedicated staff to smaller inmate groups. Review: Inmate Classification.","is_correct":false},{"text":"Single housing","isCorrect":false,"rationale":"'Single housing' is incorrect. The correct answer is 'Decentralized housing with dedicated staff'. Unit management assigns dedicated staff to smaller inmate groups. Review: Inmate Classification.","is_correct":false},{"text":"Temporary placement","isCorrect":false,"rationale":"'Temporary placement' is incorrect. The correct answer is 'Decentralized housing with dedicated staff'. Unit management assigns dedicated staff to smaller inmate groups. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Decentralized housing with dedicated staff","isCorrect":true,"rationale":"Unit management assigns dedicated staff to smaller inmate groups.","is_correct":true},{"text":"Centralized control of all housing units","is_correct":false,"rationale":"Unit management does the opposite: it hands decisions to small units, each with its own staff team."},{"text":"Rotating guards among housing units daily","is_correct":false,"rationale":"Unit management assigns a stable, dedicated team to each unit; daily rotation is what it replaces."},{"text":"Housing all inmates in one large dormitory","is_correct":false,"rationale":"Unit management divides the population into small, semi-autonomous units instead of one large dormitory."}]$opt$::jsonb),
  ('ca_107', $opt$[{"text":"Separating vulnerable inmates for safety","isCorrect":true,"rationale":"Protective custody protects inmates at risk from general population.","is_correct":true},{"text":"Solitary for punishment","isCorrect":false,"rationale":"'Solitary for punishment' is incorrect. The correct answer is 'Separating vulnerable inmates for safety'. Protective custody protects inmates at risk from general population. Review: Inmate Classification.","is_correct":false},{"text":"Work assignment","isCorrect":false,"rationale":"'Work assignment' is incorrect. The correct answer is 'Separating vulnerable inmates for safety'. Protective custody protects inmates at risk from general population. Review: Inmate Classification.","is_correct":false},{"text":"Medical isolation","isCorrect":false,"rationale":"'Medical isolation' is incorrect. The correct answer is 'Separating vulnerable inmates for safety'. Protective custody protects inmates at risk from general population. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Separating vulnerable inmates for safety","isCorrect":true,"rationale":"Protective custody protects inmates at risk from general population.","is_correct":true},{"text":"Isolating inmates as a disciplinary penalty","is_correct":false,"rationale":"That is disciplinary segregation, a punishment. Protective custody separates inmates to protect them, not to punish them."},{"text":"Separating sick inmates to prevent contagion","is_correct":false,"rationale":"That is medical isolation. Protective custody is for inmates at risk of harm from other inmates."},{"text":"Holding detainees who await their trial","is_correct":false,"rationale":"That describes pre-trial detention, not protective custody."}]$opt$::jsonb),
  ('ca_117', $opt$[{"text":"Dynamic risk factors that cause crime","isCorrect":true,"rationale":"Criminogenic needs are changeable factors linked to criminal behavior.","is_correct":true},{"text":"Basic needs","isCorrect":false,"rationale":"'Basic needs' is incorrect. The correct answer is 'Dynamic risk factors that cause crime'. Criminogenic needs are changeable factors linked to criminal behavior. Review: Inmate Classification.","is_correct":false},{"text":"Medical needs","isCorrect":false,"rationale":"'Medical needs' is incorrect. The correct answer is 'Dynamic risk factors that cause crime'. Criminogenic needs are changeable factors linked to criminal behavior. Review: Inmate Classification.","is_correct":false},{"text":"Educational needs","isCorrect":false,"rationale":"'Educational needs' is incorrect. The correct answer is 'Dynamic risk factors that cause crime'. Criminogenic needs are changeable factors linked to criminal behavior. Review: Inmate Classification.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Dynamic risk factors that cause crime","isCorrect":true,"rationale":"Criminogenic needs are changeable factors linked to criminal behavior.","is_correct":true},{"text":"Static risk factors such as criminal history","is_correct":false,"rationale":"Static factors like past offenses cannot change. Criminogenic needs are the dynamic, changeable factors linked to offending."},{"text":"Basic needs like food, shelter and clothing","is_correct":false,"rationale":"Basic needs matter for welfare but are not the crime-related factors that treatment targets."},{"text":"Health needs met by the prison clinic","is_correct":false,"rationale":"Medical needs are non-criminogenic: they do not directly drive criminal behavior."}]$opt$::jsonb),
  ('ca_041', $opt$[{"text":"Solitary confinement and labor","isCorrect":true,"rationale":"The Pennsylvania System emphasized solitary confinement with in-cell labor.","is_correct":true},{"text":"Group housing","isCorrect":false,"rationale":"'Group housing' is incorrect. The correct answer is 'Solitary confinement and labor'. The Pennsylvania System emphasized solitary confinement with in-cell labor. Review: Institutional Corrections.","is_correct":false},{"text":"Open prison","isCorrect":false,"rationale":"'Open prison' is incorrect. The correct answer is 'Solitary confinement and labor'. The Pennsylvania System emphasized solitary confinement with in-cell labor. Review: Institutional Corrections.","is_correct":false},{"text":"No work","isCorrect":false,"rationale":"'No work' is incorrect. The correct answer is 'Solitary confinement and labor'. The Pennsylvania System emphasized solitary confinement with in-cell labor. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Solitary confinement and labor","isCorrect":true,"rationale":"The Pennsylvania System emphasized solitary confinement with in-cell labor.","is_correct":true},{"text":"Silent congregate work by day","is_correct":false,"rationale":"That is the Auburn (congregate) system. The Pennsylvania system kept inmates alone day and night."},{"text":"Progressive stages toward release","is_correct":false,"rationale":"That describes the Irish (Crofton) system, not the Pennsylvania separate system."},{"text":"Earning marks for early release","is_correct":false,"rationale":"That is Maconochie's mark system, developed on Norfolk Island."}]$opt$::jsonb),
  ('ca_042', $opt$[{"text":"Silent work together, separate at night","isCorrect":true,"rationale":"The Auburn System had prisoners work silently together during day but separate at night.","is_correct":true},{"text":"Complete solitary","isCorrect":false,"rationale":"'Complete solitary' is incorrect. The correct answer is 'Silent work together, separate at night'. The Auburn System had prisoners work silently together during day but separate at night. Review: Institutional Corrections.","is_correct":false},{"text":"Open living","isCorrect":false,"rationale":"'Open living' is incorrect. The correct answer is 'Silent work together, separate at night'. The Auburn System had prisoners work silently together during day but separate at night. Review: Institutional Corrections.","is_correct":false},{"text":"No discipline","isCorrect":false,"rationale":"'No discipline' is incorrect. The correct answer is 'Silent work together, separate at night'. The Auburn System had prisoners work silently together during day but separate at night. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Silent work together, separate at night","isCorrect":true,"rationale":"The Auburn System had prisoners work silently together during day but separate at night.","is_correct":true},{"text":"Solitary confinement day and night with labor","is_correct":false,"rationale":"That is the Pennsylvania (separate) system. Auburn let inmates work together in silence."},{"text":"Open camps with work outside the walls","is_correct":false,"rationale":"Open institutions came much later. Auburn was a walled congregate prison."},{"text":"Progressive stages ending in conditional release","is_correct":false,"rationale":"That describes the stages of the Irish system, not the Auburn silent system."}]$opt$::jsonb),
  ('ca_056', $opt$[{"text":"Progressive stage system with early release","isCorrect":true,"rationale":"The Irish System introduced progressive stages and early release for good behavior.","is_correct":true},{"text":"No early release","isCorrect":false,"rationale":"'No early release' is incorrect. The correct answer is 'Progressive stage system with early release'. The Irish System introduced progressive stages and early release for good behavior. Review: Institutional Corrections.","is_correct":false},{"text":"Death penalty system","isCorrect":false,"rationale":"'Death penalty system' is incorrect. The correct answer is 'Progressive stage system with early release'. The Irish System introduced progressive stages and early release for good behavior. Review: Institutional Corrections.","is_correct":false},{"text":"No stages","isCorrect":false,"rationale":"'No stages' is incorrect. The correct answer is 'Progressive stage system with early release'. The Irish System introduced progressive stages and early release for good behavior. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Progressive stage system with early release","isCorrect":true,"rationale":"The Irish System introduced progressive stages and early release for good behavior.","is_correct":true},{"text":"Silent congregate labor in a walled prison","is_correct":false,"rationale":"That is the Auburn system. The Irish system moved inmates through stages toward a ticket of leave."},{"text":"Total solitary confinement for the whole sentence","is_correct":false,"rationale":"That is the Pennsylvania system."},{"text":"Fixed sentences served without any remission","is_correct":false,"rationale":"The Irish system rewarded progress with earlier release; fixed terms without remission are the opposite."}]$opt$::jsonb),
  ('ca_057', $opt$[{"text":"Focus on rehabilitation of young offenders","isCorrect":true,"rationale":"The Reformatory Movement emphasized rehabilitation especially for young offenders.","is_correct":true},{"text":"Maximum punishment","isCorrect":false,"rationale":"'Maximum punishment' is incorrect. The correct answer is 'Focus on rehabilitation of young offenders'. The Reformatory Movement emphasized rehabilitation especially for young offenders. Review: Institutional Corrections.","is_correct":false},{"text":"No rehabilitation","isCorrect":false,"rationale":"'No rehabilitation' is incorrect. The correct answer is 'Focus on rehabilitation of young offenders'. The Reformatory Movement emphasized rehabilitation especially for young offenders. Review: Institutional Corrections.","is_correct":false},{"text":"Adult focus only","isCorrect":false,"rationale":"'Adult focus only' is incorrect. The correct answer is 'Focus on rehabilitation of young offenders'. The Reformatory Movement emphasized rehabilitation especially for young offenders. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Focus on rehabilitation of young offenders","isCorrect":true,"rationale":"The Reformatory Movement emphasized rehabilitation especially for young offenders.","is_correct":true},{"text":"Solitary penitence for adult felons","is_correct":false,"rationale":"That is the Pennsylvania penitentiary idea. The reformatory movement (Elmira, 1876) targeted young first offenders."},{"text":"Fixed sentences to deter young offenders","is_correct":false,"rationale":"Reformatories used indeterminate sentences tied to reform, not fixed deterrent terms."},{"text":"Hard labor to repay victims of crime","is_correct":false,"rationale":"Restitution through labor is not what defined the reformatory movement."}]$opt$::jsonb),
  ('ca_065', $opt$[{"text":"Bureau of Corrections Act of 2013","isCorrect":true,"rationale":"RA 10575 is the Bureau of Corrections Act of 2013 that mandates rehabilitation.","is_correct":true},{"text":"Anti-Drug Law","isCorrect":false,"rationale":"'Anti-Drug Law' is incorrect. The correct answer is 'Bureau of Corrections Act of 2013'. RA 10575 is the Bureau of Corrections Act of 2013 that mandates rehabilitation. Review: Institutional Corrections.","is_correct":false},{"text":"Cybercrime Law","isCorrect":false,"rationale":"'Cybercrime Law' is incorrect. The correct answer is 'Bureau of Corrections Act of 2013'. RA 10575 is the Bureau of Corrections Act of 2013 that mandates rehabilitation. Review: Institutional Corrections.","is_correct":false},{"text":"Anti-Terrorism Law","isCorrect":false,"rationale":"'Anti-Terrorism Law' is incorrect. The correct answer is 'Bureau of Corrections Act of 2013'. RA 10575 is the Bureau of Corrections Act of 2013 that mandates rehabilitation. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Bureau of Corrections Act of 2013","isCorrect":true,"rationale":"RA 10575 is the Bureau of Corrections Act of 2013 that mandates rehabilitation.","is_correct":true},{"text":"Juvenile Justice and Welfare Act","is_correct":false,"rationale":"That is RA 9344 (2006), later amended by RA 10630."},{"text":"Comprehensive Dangerous Drugs Act","is_correct":false,"rationale":"That is RA 9165 (2002)."},{"text":"Good Conduct Time Allowance Law","is_correct":false,"rationale":"The good conduct time allowance rules were amended by RA 10592 (2013), not RA 10575."}]$opt$::jsonb),
  ('ca_095', $opt$[{"text":"Progressive stage system with early release","isCorrect":true,"rationale":"The Irish System introduced progressive stages and conditional release.","is_correct":true},{"text":"Maximum security only","isCorrect":false,"rationale":"'Maximum security only' is incorrect. The correct answer is 'Progressive stage system with early release'. The Irish System introduced progressive stages and conditional release. Review: Institutional Corrections.","is_correct":false},{"text":"Solitary confinement","isCorrect":false,"rationale":"'Solitary confinement' is incorrect. The correct answer is 'Progressive stage system with early release'. The Irish System introduced progressive stages and conditional release. Review: Institutional Corrections.","is_correct":false},{"text":"Death penalty","isCorrect":false,"rationale":"'Death penalty' is incorrect. The correct answer is 'Progressive stage system with early release'. The Irish System introduced progressive stages and conditional release. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Progressive stage system with early release","isCorrect":true,"rationale":"The Irish System introduced progressive stages and conditional release.","is_correct":true},{"text":"Congregate silent labor and separate cells","is_correct":false,"rationale":"That is the Auburn system."},{"text":"Strict separate confinement for every inmate","is_correct":false,"rationale":"That is the Pennsylvania system."},{"text":"Indeterminate sentences for young first offenders","is_correct":false,"rationale":"That is the Elmira reformatory model. The Irish system is the staged progression to a ticket of leave."}]$opt$::jsonb),
  ('ca_104', $opt$[{"text":"Earning credits toward release through behavior","isCorrect":true,"rationale":"The mark system allowed inmates to earn early release through good behavior.","is_correct":true},{"text":"Branding inmates","isCorrect":false,"rationale":"'Branding inmates' is incorrect. The correct answer is 'Earning credits toward release through behavior'. The mark system allowed inmates to earn early release through good behavior. Review: Institutional Corrections.","is_correct":false},{"text":"Identification system","isCorrect":false,"rationale":"'Identification system' is incorrect. The correct answer is 'Earning credits toward release through behavior'. The mark system allowed inmates to earn early release through good behavior. Review: Institutional Corrections.","is_correct":false},{"text":"Punishment marks","isCorrect":false,"rationale":"'Punishment marks' is incorrect. The correct answer is 'Earning credits toward release through behavior'. The mark system allowed inmates to earn early release through good behavior. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Earning credits toward release through behavior","isCorrect":true,"rationale":"The mark system allowed inmates to earn early release through good behavior.","is_correct":true},{"text":"Branding offenders to show their past crimes","is_correct":false,"rationale":"Branding was an old corporal penalty. The mark system means earning marks (credits) toward release."},{"text":"Numbering inmates for identification records","is_correct":false,"rationale":"Inmate numbers are for identification. The mark system rewards work and conduct with credits."},{"text":"Fixed release date set by the court at sentencing","is_correct":false,"rationale":"The mark system made release depend on the marks earned, not on a fixed date."}]$opt$::jsonb),
  ('ca_114', $opt$[{"text":"First true correctional institution in US","isCorrect":true,"rationale":"Walnut Street Jail (1790) pioneered the penitentiary concept.","is_correct":true},{"text":"Last prison built","isCorrect":false,"rationale":"'Last prison built' is incorrect. The correct answer is 'First true correctional institution in US'. Walnut Street Jail (1790) pioneered the penitentiary concept. Review: Institutional Corrections.","is_correct":false},{"text":"Largest prison","isCorrect":false,"rationale":"'Largest prison' is incorrect. The correct answer is 'First true correctional institution in US'. Walnut Street Jail (1790) pioneered the penitentiary concept. Review: Institutional Corrections.","is_correct":false},{"text":"First womens prison","isCorrect":false,"rationale":"'First womens prison' is incorrect. The correct answer is 'First true correctional institution in US'. Walnut Street Jail (1790) pioneered the penitentiary concept. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"First true correctional institution in US","isCorrect":true,"rationale":"Walnut Street Jail (1790) pioneered the penitentiary concept.","is_correct":true},{"text":"First prison to use the Auburn silent system","is_correct":false,"rationale":"The silent system began at Auburn Prison, New York (1816). Walnut Street (1790) used solitary cells."},{"text":"First reformatory for young first offenders","is_correct":false,"rationale":"That is Elmira Reformatory (1876)."},{"text":"First federal prison of the United States","is_correct":false,"rationale":"Walnut Street was a Philadelphia jail, not a federal prison."}]$opt$::jsonb),
  ('ca_120', $opt$[{"text":"Treating crime as illness to be cured","isCorrect":true,"rationale":"The medical model views criminality as a treatable condition.","is_correct":true},{"text":"Hospital in prison","isCorrect":false,"rationale":"'Hospital in prison' is incorrect. The correct answer is 'Treating crime as illness to be cured'. The medical model views criminality as a treatable condition. Review: Institutional Corrections.","is_correct":false},{"text":"Drug treatment only","isCorrect":false,"rationale":"'Drug treatment only' is incorrect. The correct answer is 'Treating crime as illness to be cured'. The medical model views criminality as a treatable condition. Review: Institutional Corrections.","is_correct":false},{"text":"Physical health focus","isCorrect":false,"rationale":"'Physical health focus' is incorrect. The correct answer is 'Treating crime as illness to be cured'. The medical model views criminality as a treatable condition. Review: Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Treating crime as illness to be cured","isCorrect":true,"rationale":"The medical model views criminality as a treatable condition.","is_correct":true},{"text":"Punishing crime in proportion to its harm","is_correct":false,"rationale":"That is the justice (just deserts) model."},{"text":"Keeping offenders confined to protect society","is_correct":false,"rationale":"That is incapacitation, the aim of the custodial model."},{"text":"Providing hospital care to sick inmates","is_correct":false,"rationale":"Prison health care is a service. The medical model treats criminality itself as a condition to diagnose and cure."}]$opt$::jsonb),
  ('ca_016', $opt$[{"text":"Probation Law of 1976","isCorrect":true,"rationale":"PD 968 is the Probation Law of 1976, establishing the probation system in the Philippines.","is_correct":true},{"text":"Prison Law","isCorrect":false,"rationale":"'Prison Law' is incorrect. The correct answer is 'Probation Law of 1976'. PD 968 is the Probation Law of 1976, establishing the probation system in the Philippines. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Parole Law","isCorrect":false,"rationale":"'Parole Law' is incorrect. The correct answer is 'Probation Law of 1976'. PD 968 is the Probation Law of 1976, establishing the probation system in the Philippines. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Amnesty Law","isCorrect":false,"rationale":"'Amnesty Law' is incorrect. The correct answer is 'Probation Law of 1976'. PD 968 is the Probation Law of 1976, establishing the probation system in the Philippines. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Probation Law of 1976","isCorrect":true,"rationale":"PD 968 is the Probation Law of 1976, establishing the probation system in the Philippines.","is_correct":true},{"text":"Indeterminate Sentence Law","is_correct":false,"rationale":"That is Act No. 4103 (1933), which also governs parole."},{"text":"DILG Act of 1990","is_correct":false,"rationale":"That is RA 6975, which created the DILG, PNP, BJMP and BFP."},{"text":"Juvenile Justice Act of 2006","is_correct":false,"rationale":"That is RA 9344."}]$opt$::jsonb),
  ('ca_043', $opt$[{"text":"Parole after prison, probation instead of","isCorrect":true,"rationale":"Parole is release after serving part of prison sentence; probation is instead of imprisonment.","is_correct":true},{"text":"Same thing","isCorrect":false,"rationale":"'Same thing' is incorrect. The correct answer is 'Parole after prison, probation instead of'. Parole is release after serving part of prison sentence; probation is instead of imprisonment. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Both after prison","isCorrect":false,"rationale":"'Both after prison' is incorrect. The correct answer is 'Parole after prison, probation instead of'. Parole is release after serving part of prison sentence; probation is instead of imprisonment. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Neither involves supervision","isCorrect":false,"rationale":"'Neither involves supervision' is incorrect. The correct answer is 'Parole after prison, probation instead of'. Parole is release after serving part of prison sentence; probation is instead of imprisonment. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Parole after prison, probation instead of","isCorrect":true,"rationale":"Parole is release after serving part of prison sentence; probation is instead of imprisonment.","is_correct":true},{"text":"Probation after prison, parole instead of","is_correct":false,"rationale":"Reversed: parole is release after serving part of a prison term; probation is given instead of imprisonment."},{"text":"Parole is granted by the court, probation by the board","is_correct":false,"rationale":"Reversed: probation is granted by the trial court; parole by the Board of Pardons and Parole."},{"text":"Both are given only after the full sentence","is_correct":false,"rationale":"Neither waits for the full sentence: probation replaces prison, and parole is release before the maximum term ends."}]$opt$::jsonb),
  ('ca_058', $opt$[{"text":"Strict monitoring with frequent contact","isCorrect":true,"rationale":"Intensive supervision involves strict monitoring with frequent contact between officer and probationer.","is_correct":true},{"text":"No supervision","isCorrect":false,"rationale":"'No supervision' is incorrect. The correct answer is 'Strict monitoring with frequent contact'. Intensive supervision involves strict monitoring with frequent contact between officer and probationer. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Minimal contact","isCorrect":false,"rationale":"'Minimal contact' is incorrect. The correct answer is 'Strict monitoring with frequent contact'. Intensive supervision involves strict monitoring with frequent contact between officer and probationer. Review: Non-Institutional Corrections.","is_correct":false},{"text":"No conditions","isCorrect":false,"rationale":"'No conditions' is incorrect. The correct answer is 'Strict monitoring with frequent contact'. Intensive supervision involves strict monitoring with frequent contact between officer and probationer. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Strict monitoring with frequent contact","isCorrect":true,"rationale":"Intensive supervision involves strict monitoring with frequent contact between officer and probationer.","is_correct":true},{"text":"Monthly reporting by mail to the officer","is_correct":false,"rationale":"That is minimal supervision. Intensive supervision means frequent, close contact."},{"text":"Release without conditions after sentencing","is_correct":false,"rationale":"Probation always has conditions; intensive supervision adds stricter ones."},{"text":"Confinement in a halfway house at night","is_correct":false,"rationale":"That is residential community corrections, not intensive supervision probation."}]$opt$::jsonb),
  ('ca_059', $opt$[{"text":"Tracking offenders with electronic devices","isCorrect":true,"rationale":"Electronic monitoring uses devices like ankle bracelets to track offender location.","is_correct":true},{"text":"No monitoring","isCorrect":false,"rationale":"'No monitoring' is incorrect. The correct answer is 'Tracking offenders with electronic devices'. Electronic monitoring uses devices like ankle bracelets to track offender location. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Paper monitoring","isCorrect":false,"rationale":"'Paper monitoring' is incorrect. The correct answer is 'Tracking offenders with electronic devices'. Electronic monitoring uses devices like ankle bracelets to track offender location. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Phone calls only","isCorrect":false,"rationale":"'Phone calls only' is incorrect. The correct answer is 'Tracking offenders with electronic devices'. Electronic monitoring uses devices like ankle bracelets to track offender location. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Tracking offenders with electronic devices","isCorrect":true,"rationale":"Electronic monitoring uses devices like ankle bracelets to track offender location.","is_correct":true},{"text":"Recording inmates' calls inside the prison","is_correct":false,"rationale":"Call recording is a prison security practice, not electronic monitoring of offenders in the community."},{"text":"Checking in with an officer by phone weekly","is_correct":false,"rationale":"Telephone reporting relies on the offender calling in. Electronic monitoring tracks location with a device."},{"text":"Watching cell blocks through CCTV cameras","is_correct":false,"rationale":"CCTV is institutional surveillance. Electronic monitoring tracks a person, for example with an ankle device, outside prison."}]$opt$::jsonb),
  ('ca_105', $opt$[{"text":"Combination of incarceration and probation","isCorrect":true,"rationale":"Split sentence combines jail time with a period of probation.","is_correct":true},{"text":"Two separate crimes","isCorrect":false,"rationale":"'Two separate crimes' is incorrect. The correct answer is 'Combination of incarceration and probation'. Split sentence combines jail time with a period of probation. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Appeal process","isCorrect":false,"rationale":"'Appeal process' is incorrect. The correct answer is 'Combination of incarceration and probation'. Split sentence combines jail time with a period of probation. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Consecutive sentences","isCorrect":false,"rationale":"'Consecutive sentences' is incorrect. The correct answer is 'Combination of incarceration and probation'. Split sentence combines jail time with a period of probation. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Combination of incarceration and probation","isCorrect":true,"rationale":"Split sentence combines jail time with a period of probation.","is_correct":true},{"text":"Two sentences served one after the other","is_correct":false,"rationale":"That is a consecutive sentence."},{"text":"Two sentences served at the same time","is_correct":false,"rationale":"That is a concurrent sentence."},{"text":"Sentence divided between two co-accused","is_correct":false,"rationale":"Each accused receives their own sentence. A split sentence combines a short jail term with probation for one offender."}]$opt$::jsonb),
  ('ca_110', $opt$[{"text":"Facility for daily check-in and programming","isCorrect":true,"rationale":"Day reporting centers require daily attendance for treatment and monitoring.","is_correct":true},{"text":"Overnight jail","isCorrect":false,"rationale":"'Overnight jail' is incorrect. The correct answer is 'Facility for daily check-in and programming'. Day reporting centers require daily attendance for treatment and monitoring. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Maximum security","isCorrect":false,"rationale":"'Maximum security' is incorrect. The correct answer is 'Facility for daily check-in and programming'. Day reporting centers require daily attendance for treatment and monitoring. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Hospital","isCorrect":false,"rationale":"'Hospital' is incorrect. The correct answer is 'Facility for daily check-in and programming'. Day reporting centers require daily attendance for treatment and monitoring. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Facility for daily check-in and programming","isCorrect":true,"rationale":"Day reporting centers require daily attendance for treatment and monitoring.","is_correct":true},{"text":"Facility where offenders sleep but work outside","is_correct":false,"rationale":"That is a halfway house or work-release center; a day reporting center does not involve living there."},{"text":"Office where probationers report once a month","is_correct":false,"rationale":"Monthly reporting is regular probation. A day reporting center requires daily attendance."},{"text":"Jail where inmates serve weekend sentences","is_correct":false,"rationale":"That is intermittent (weekend) confinement."}]$opt$::jsonb),
  ('ca_115', $opt$[{"text":"Minor violations lead to major crimes","isCorrect":true,"rationale":"Broken windows theory suggests addressing minor violations prevents escalation.","is_correct":true},{"text":"Prison maintenance","isCorrect":false,"rationale":"'Prison maintenance' is incorrect. The correct answer is 'Minor violations lead to major crimes'. Broken windows theory suggests addressing minor violations prevents escalation. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Escape prevention","isCorrect":false,"rationale":"'Escape prevention' is incorrect. The correct answer is 'Minor violations lead to major crimes'. Broken windows theory suggests addressing minor violations prevents escalation. Review: Non-Institutional Corrections.","is_correct":false},{"text":"Work programs","isCorrect":false,"rationale":"'Work programs' is incorrect. The correct answer is 'Minor violations lead to major crimes'. Broken windows theory suggests addressing minor violations prevents escalation. Review: Non-Institutional Corrections.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Minor violations lead to major crimes","isCorrect":true,"rationale":"Broken windows theory suggests addressing minor violations prevents escalation.","is_correct":true},{"text":"Crime rises when guardians are absent","is_correct":false,"rationale":"That is routine activity theory: a motivated offender, a suitable target and no capable guardian."},{"text":"Offenders weigh costs and benefits first","is_correct":false,"rationale":"That is rational choice theory."},{"text":"Labeling first offenders deepens deviance","is_correct":false,"rationale":"That is labeling theory."}]$opt$::jsonb),
  ('ca_060', $opt$[{"text":"Pardon is individual, amnesty is general","isCorrect":true,"rationale":"Pardon is granted to individuals; amnesty is a general pardon to groups, usually for political offenses.","is_correct":true},{"text":"Same thing","isCorrect":false,"rationale":"'Same thing' is incorrect. The correct answer is 'Pardon is individual, amnesty is general'. Pardon is granted to individuals; amnesty is a general pardon to groups, usually for political offenses. Review: Pardon and Amnesty.","is_correct":false},{"text":"Both are general","isCorrect":false,"rationale":"'Both are general' is incorrect. The correct answer is 'Pardon is individual, amnesty is general'. Pardon is granted to individuals; amnesty is a general pardon to groups, usually for political offenses. Review: Pardon and Amnesty.","is_correct":false},{"text":"Both are individual","isCorrect":false,"rationale":"'Both are individual' is incorrect. The correct answer is 'Pardon is individual, amnesty is general'. Pardon is granted to individuals; amnesty is a general pardon to groups, usually for political offenses. Review: Pardon and Amnesty.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Pardon is individual, amnesty is general","isCorrect":true,"rationale":"Pardon is granted to individuals; amnesty is a general pardon to groups, usually for political offenses.","is_correct":true},{"text":"Amnesty is individual, pardon is general","is_correct":false,"rationale":"Reversed: a pardon is given to an individual; amnesty is granted to a class of persons, often political offenders."},{"text":"Pardon needs Congress, amnesty does not","is_correct":false,"rationale":"Reversed: amnesty needs the concurrence of a majority of Congress; pardon does not (1987 Constitution, Art. VII, Sec. 19)."},{"text":"Pardon erases the crime, amnesty does not","is_correct":false,"rationale":"Reversed: amnesty treats the offense as if it had not been committed; pardon relieves the penalty but not the fact of the crime."}]