  ('ca_045', $opt$[{"text":"Maximum, medium, minimum","isCorrect":true,"rationale":"Philippine prisons have maximum, medium, and minimum security classifications.","is_correct":true},{"text":"High, low","isCorrect":false,"rationale":"'High, low' is incorrect. The correct answer is 'Maximum, medium, minimum'. Philippine prisons have maximum, medium, and minimum security classifications. Review: Prison Security.","is_correct":false},{"text":"Only maximum","isCorrect":false,"rationale":"'Only maximum' is incorrect. The correct answer is 'Maximum, medium, minimum'. Philippine prisons have maximum, medium, and minimum security classifications. Review: Prison Security.","is_correct":false},{"text":"No classification","isCorrect":false,"rationale":"'No classification' is incorrect. The correct answer is 'Maximum, medium, minimum'. Philippine prisons have maximum, medium, and minimum security classifications. Review: Prison Security.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Maximum, medium, minimum","isCorrect":true,"rationale":"Philippine prisons have maximum, medium, and minimum security classifications.","is_correct":true},{"text":"Super-maximum, maximum, medium","is_correct":false,"rationale":"The Philippines has no super-maximum level; the three levels are maximum, medium and minimum."},{"text":"Closed, semi-open, open","is_correct":false,"rationale":"These are terms used elsewhere. The Bureau of Corrections uses maximum, medium and minimum security."},{"text":"Maximum, minimum, open","is_correct":false,"rationale":"There are three levels and the middle one, medium security, is missing here; 'open' is not one of them."}]$opt$::jsonb),
