  ('cdi_057', $opt$[{"text":"Strip, grid, zone, wheel, spiral","isCorrect":true,"rationale":"Crime scene search methods include strip, grid, zone, wheel, and spiral patterns.","is_correct":true},{"text":"Fast, slow, medium","isCorrect":false,"rationale":"'Fast, slow, medium' is incorrect. The correct answer is 'Strip, grid, zone, wheel, spiral'. Crime scene search methods include strip, grid, zone, wheel, and spiral patterns. Review: Crime Scene Investigation.","is_correct":false},{"text":"Day, night, twilight","isCorrect":false,"rationale":"'Day, night, twilight' is incorrect. The correct answer is 'Strip, grid, zone, wheel, spiral'. Crime scene search methods include strip, grid, zone, wheel, and spiral patterns. Review: Crime Scene Investigation.","is_correct":false},{"text":"Indoor only","isCorrect":false,"rationale":"'Indoor only' is incorrect. The correct answer is 'Strip, grid, zone, wheel, spiral'. Crime scene search methods include strip, grid, zone, wheel, and spiral patterns. Review: Crime Scene Investigation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Strip, grid, zone, wheel, spiral","isCorrect":true,"rationale":"Crime scene search methods include strip, grid, zone, wheel, and spiral patterns.","is_correct":true},{"text":"Photograph, sketch, note, collect","is_correct":false,"rationale":"Those are documentation and collection steps, not search methods."},{"text":"Inner, outer and extended perimeters","is_correct":false,"rationale":"Those are scene perimeters (cordons), not search patterns."},{"text":"Survey, search, seal, release","is_correct":false,"rationale":"Those are general stages of processing a scene, not the search methods."}]$opt$::jsonb),
  ('cdi_058', $opt$[{"text":"Every contact leaves a trace","isCorrect":true,"rationale":"Locard's principle states that every contact between two objects leaves a trace.","is_correct":true},{"text":"No evidence is ever left","isCorrect":false,"rationale":"'No evidence is ever left' is incorrect. The correct answer is 'Every contact leaves a trace'. Locard's principle states that every contact between two objects leaves a trace. Review: Crime Scene Investigation.","is_correct":false},{"text":"Only blood is evidence","isCorrect":false,"rationale":"'Only blood is evidence' is incorrect. The correct answer is 'Every contact leaves a trace'. Locard's principle states that every contact between two objects leaves a trace. Review: Crime Scene Investigation.","is_correct":false},{"text":"Fingerprints are unreliable","isCorrect":false,"rationale":"'Fingerprints are unreliable' is incorrect. The correct answer is 'Every contact leaves a trace'. Locard's principle states that every contact between two objects leaves a trace. Review: Crime Scene Investigation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Every contact leaves a trace","isCorrect":true,"rationale":"Locard's principle states that every contact between two objects leaves a trace.","is_correct":true},{"text":"Every crime has a motive and opportunity","is_correct":false,"rationale":"Motive and opportunity are investigative concepts, not Locard's principle."},{"text":"Evidence is lost as time passes","is_correct":false,"rationale":"That happens in practice, but it is not Locard's Exchange Principle."},{"text":"No two fingerprints are ever alike","is_correct":false,"rationale":"That is the principle of individuality of fingerprints, not Locard's."}]$opt$::jsonb),
