  ('cdi_103', $opt$[{"text":"Every contact leaves a trace","isCorrect":true,"rationale":"Locard stated that every contact between two items results in an exchange of material.","is_correct":true},{"text":"Evidence can be destroyed","isCorrect":false,"rationale":"'Evidence can be destroyed' is incorrect. The correct answer is 'Every contact leaves a trace'. Locard stated that every contact between two items results in an exchange of material. Review: Crime Scene Investigation.","is_correct":false},{"text":"Witnesses are unreliable","isCorrect":false,"rationale":"'Witnesses are unreliable' is incorrect. The correct answer is 'Every contact leaves a trace'. Locard stated that every contact between two items results in an exchange of material. Review: Crime Scene Investigation.","is_correct":false},{"text":"Crime scenes cannot be processed","isCorrect":false,"rationale":"'Crime scenes cannot be processed' is incorrect. The correct answer is 'Every contact leaves a trace'. Locard stated that every contact between two items results in an exchange of material. Review: Crime Scene Investigation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Every contact leaves a trace","isCorrect":true,"rationale":"Locard stated that every contact between two items results in an exchange of material.","is_correct":true},{"text":"Physical evidence cannot lie","is_correct":false,"rationale":"A saying about the reliability of evidence (attributed to Kirk), not Locard's Exchange Principle."},{"text":"The scene must be secured first","is_correct":false,"rationale":"That is a rule of scene management, not Locard's principle."},{"text":"Trace evidence is always visible","is_correct":false,"rationale":"False, and not the principle: much trace evidence is microscopic."}]$opt$::jsonb),
