  ('cdi_074', $opt$[{"text":"Documentation of drug evidence handling","isCorrect":true,"rationale":"Chain of custody documents every person who handled drug evidence from seizure to court.","is_correct":true},{"text":"Drug distribution network","isCorrect":false,"rationale":"'Drug distribution network' is incorrect. The correct answer is 'Documentation of drug evidence handling'. Chain of custody documents every person who handled drug evidence from seizure to court. Review: Drug Education and Vice Control.","is_correct":false},{"text":"Drug manufacturing","isCorrect":false,"rationale":"'Drug manufacturing' is incorrect. The correct answer is 'Documentation of drug evidence handling'. Chain of custody documents every person who handled drug evidence from seizure to court. Review: Drug Education and Vice Control.","is_correct":false},{"text":"Drug use pattern","isCorrect":false,"rationale":"'Drug use pattern' is incorrect. The correct answer is 'Documentation of drug evidence handling'. Chain of custody documents every person who handled drug evidence from seizure to court. Review: Drug Education and Vice Control.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Documentation of drug evidence handling","isCorrect":true,"rationale":"Chain of custody documents every person who handled drug evidence from seizure to court.","is_correct":true},{"text":"Network of persons who distribute illegal drugs","is_correct":false,"rationale":"That is a distribution network, not chain of custody."},{"text":"Laboratory test that confirms a drug's identity","is_correct":false,"rationale":"That is the confirmatory test. Chain of custody documents who handled the evidence, and when."},{"text":"Order in which suspects are arrested in a buy-bust","is_correct":false,"rationale":"The order of arrests is not chain of custody."}]$opt$::jsonb),
