  ('cj_027', $opt$[{"text":"Convicted twice for crimes under same title of RPC","isCorrect":true,"rationale":"A recidivist is one who, at the time of trial, has been previously convicted of a crime under the same title of the RPC.","is_correct":true},{"text":"First-time offender","isCorrect":false,"rationale":"'First-time offender' is incorrect. The correct answer is 'Convicted twice for crimes under same title of RPC'. A recidivist is one who, at the time of trial, has been previously convicted of a crime under the same title of the RPC. Review: Aggravating Circumstances.","is_correct":false},{"text":"Habitual delinquent","isCorrect":false,"rationale":"'Habitual delinquent' is incorrect. The correct answer is 'Convicted twice for crimes under same title of RPC'. A recidivist is one who, at the time of trial, has been previously convicted of a crime under the same title of the RPC. Review: Aggravating Circumstances.","is_correct":false},{"text":"Quasi-recidivist","isCorrect":false,"rationale":"'Quasi-recidivist' is incorrect. The correct answer is 'Convicted twice for crimes under same title of RPC'. A recidivist is one who, at the time of trial, has been previously convicted of a crime under the same title of the RPC. Review: Aggravating Circumstances.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Convicted twice for crimes under same title of RPC","isCorrect":true,"rationale":"A recidivist is one who, at the time of trial, has been previously convicted of a crime under the same title of the RPC.","is_correct":true},{"text":"Convicted within ten years of release, a third time or more","is_correct":false,"rationale":"That is habitual delinquency (Art. 62): a third or later conviction for certain crimes within ten years."},{"text":"Committing a new felony while serving sentence","is_correct":false,"rationale":"That is quasi-recidivism (Art. 160)."},{"text":"Previously punished for an offense with an equal or greater penalty","is_correct":false,"rationale":"That is reiteracion or habituality (Art. 14(10)), which does not require the same title of the Code."}]$opt$::jsonb),
  ('cj_133', $opt$[{"text":"Witness who shows antagonism to party who called them","isCorrect":true,"rationale":"A hostile witness shows antagonism and may be cross-examined by the party who called them.","is_correct":true},{"text":"Friendly witness","isCorrect":false,"rationale":"'Friendly witness' is incorrect. The correct answer is 'Witness who shows antagonism to party who called them'. A hostile witness shows antagonism and may be cross-examined by the party who called them. Review: Court Testimony.","is_correct":false},{"text":"Expert witness","isCorrect":false,"rationale":"'Expert witness' is incorrect. The correct answer is 'Witness who shows antagonism to party who called them'. A hostile witness shows antagonism and may be cross-examined by the party who called them. Review: Court Testimony.","is_correct":false},{"text":"Character witness","isCorrect":false,"rationale":"'Character witness' is incorrect. The correct answer is 'Witness who shows antagonism to party who called them'. A hostile witness shows antagonism and may be cross-examined by the party who called them. Review: Court Testimony.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Witness who shows antagonism to party who called them","isCorrect":true,"rationale":"A hostile witness shows antagonism and may be cross-examined by the party who called them.","is_correct":true},{"text":"Witness who is the opposing party in the case","is_correct":false,"rationale":"That is an adverse party witness. A hostile witness is your own witness who turns out antagonistic or evasive."},{"text":"Witness whose testimony rests on special knowledge","is_correct":false,"rationale":"That is an expert witness."},{"text":"Witness who testifies only to the accused's reputation","is_correct":false,"rationale":"That is a character witness."}]$opt$::jsonb),
  ('cj_013', $opt$[{"text":"Act/Omission, Punishable by RPC, Done with deceit/fault","isCorrect":true,"rationale":"A felony requires: (1) an act or omission, (2) punishable by the RPC, and (3) done with deceit or fault.","is_correct":true},{"text":"Intent only","isCorrect":false,"rationale":"'Intent only' is incorrect. The correct answer is 'Act/Omission, Punishable by RPC, Done with deceit/fault'. A felony requires: (1) an act or omission, (2) punishable by the RPC, and (3) done with deceit or fault. Review: Criminal Law Book I.","is_correct":false},{"text":"Damage only","isCorrect":false,"rationale":"'Damage only' is incorrect. The correct answer is 'Act/Omission, Punishable by RPC, Done with deceit/fault'. A felony requires: (1) an act or omission, (2) punishable by the RPC, and (3) done with deceit or fault. Review: Criminal Law Book I.","is_correct":false},{"text":"Motive only","isCorrect":false,"rationale":"'Motive only' is incorrect. The correct answer is 'Act/Omission, Punishable by RPC, Done with deceit/fault'. A felony requires: (1) an act or omission, (2) punishable by the RPC, and (3) done with deceit or fault. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Act/Omission, Punishable by RPC, Done with deceit/fault","isCorrect":true,"rationale":"A felony requires: (1) an act or omission, (2) punishable by the RPC, and (3) done with deceit or fault.","is_correct":true},{"text":"Act/Omission, Damage to another, Proof of motive","is_correct":false,"rationale":"Damage and motive are not elements. A felony is an act or omission punishable by the RPC, done by deceit (dolo) or fault (culpa)."},{"text":"Intent, Overt act, Consummation of the crime","is_correct":false,"rationale":"Felonies include attempted and frustrated stages and acts by culpa, so intent and consummation are not required elements."},{"text":"Act/Omission, Punishable by special law, Malice","is_correct":false,"rationale":"Acts punished by special laws are offenses, not felonies. Felonies are punished by the Revised Penal Code (Art. 3)."}]$opt$::jsonb),
  ('cj_078', $opt$[{"text":"All acts done but result not produced","isCorrect":true,"rationale":"A frustrated felony occurs when all acts are performed but the felony is not produced by causes independent of the will of the perpetrator.","is_correct":true},{"text":"Crime is complete","isCorrect":false,"rationale":"'Crime is complete' is incorrect. The correct answer is 'All acts done but result not produced'. A frustrated felony occurs when all acts are performed but the felony is not produced by causes independent of the will of the perpetrator. Review: Criminal Law Book I.","is_correct":false},{"text":"Only some acts done","isCorrect":false,"rationale":"'Only some acts done' is incorrect. The correct answer is 'All acts done but result not produced'. A frustrated felony occurs when all acts are performed but the felony is not produced by causes independent of the will of the perpetrator. Review: Criminal Law Book I.","is_correct":false},{"text":"No act performed","isCorrect":false,"rationale":"'No act performed' is incorrect. The correct answer is 'All acts done but result not produced'. A frustrated felony occurs when all acts are performed but the felony is not produced by causes independent of the will of the perpetrator. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"All acts done but result not produced","isCorrect":true,"rationale":"A frustrated felony occurs when all acts are performed but the felony is not produced by causes independent of the will of the perpetrator.","is_correct":true},{"text":"Some acts done but stopped by outside causes","is_correct":false,"rationale":"That is the attempted stage: not all acts of execution were performed."},{"text":"All acts done and the felony accomplished","is_correct":false,"rationale":"That is the consummated stage."},{"text":"Acts done that can never produce the felony","is_correct":false,"rationale":"That is an impossible crime (Art. 4(2))."}]$opt$::jsonb),
  ('cj_079', $opt$[{"text":"Murder absorbed in rebellion","isCorrect":true,"rationale":"Common crimes like murder committed in furtherance of rebellion are absorbed in the crime of rebellion.","is_correct":true},{"text":"Separate crimes","isCorrect":false,"rationale":"'Separate crimes' is incorrect. The correct answer is 'Murder absorbed in rebellion'. Common crimes like murder committed in furtherance of rebellion are absorbed in the crime of rebellion. Review: Criminal Law Book I.","is_correct":false},{"text":"Only murder punished","isCorrect":false,"rationale":"'Only murder punished' is incorrect. The correct answer is 'Murder absorbed in rebellion'. Common crimes like murder committed in furtherance of rebellion are absorbed in the crime of rebellion. Review: Criminal Law Book I.","is_correct":false},{"text":"Only rebellion punished","isCorrect":false,"rationale":"'Only rebellion punished' is incorrect. The correct answer is 'Murder absorbed in rebellion'. Common crimes like murder committed in furtherance of rebellion are absorbed in the crime of rebellion. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Murder absorbed in rebellion","isCorrect":true,"rationale":"Common crimes like murder committed in furtherance of rebellion are absorbed in the crime of rebellion.","is_correct":true},{"text":"Murder and rebellion punished separately","is_correct":false,"rationale":"Under the Hernandez doctrine, killings in furtherance of rebellion are absorbed, not punished separately."},{"text":"Rebellion absorbed in murder","is_correct":false,"rationale":"Reversed: the murder is absorbed in the rebellion, not the other way round."},{"text":"Complex crime with the graver penalty","is_correct":false,"rationale":"There is no complex crime of rebellion with murder; common crimes done in furtherance of rebellion are absorbed (People v. Hernandez)."}]$opt$::jsonb),
  ('cj_080', $opt$[{"text":"Minimum and maximum sentence imposed","isCorrect":true,"rationale":"The ISL requires courts to impose a minimum and maximum term of imprisonment.","is_correct":true},{"text":"Fixed sentence only","isCorrect":false,"rationale":"'Fixed sentence only' is incorrect. The correct answer is 'Minimum and maximum sentence imposed'. The ISL requires courts to impose a minimum and maximum term of imprisonment. Review: Criminal Law Book I.","is_correct":false},{"text":"No sentence","isCorrect":false,"rationale":"'No sentence' is incorrect. The correct answer is 'Minimum and maximum sentence imposed'. The ISL requires courts to impose a minimum and maximum term of imprisonment. Review: Criminal Law Book I.","is_correct":false},{"text":"Probation only","isCorrect":false,"rationale":"'Probation only' is incorrect. The correct answer is 'Minimum and maximum sentence imposed'. The ISL requires courts to impose a minimum and maximum term of imprisonment. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Minimum and maximum sentence imposed","isCorrect":true,"rationale":"The ISL requires courts to impose a minimum and maximum term of imprisonment.","is_correct":true},{"text":"One fixed term set by the court","is_correct":false,"rationale":"That is a straight penalty. The Indeterminate Sentence Law requires a minimum and a maximum."},{"text":"Suspension of sentence for first offenders","is_correct":false,"rationale":"That is probation (PD 968)."},{"text":"Deduction of time for good conduct","is_correct":false,"rationale":"That is good conduct time allowance."}]$opt$::jsonb),
  ('cj_081', $opt$[{"text":"Maximum 40 years even if total exceeds","isCorrect":true,"rationale":"Under the three-fold rule, the maximum duration is not more than three times the most severe penalty but shall not exceed 40 years.","is_correct":true},{"text":"Serve all sentences fully","isCorrect":false,"rationale":"'Serve all sentences fully' is incorrect. The correct answer is 'Maximum 40 years even if total exceeds'. Under the three-fold rule, the maximum duration is not more than three times the most severe penalty but shall not exceed 40 years. Review: Criminal Law Book I.","is_correct":false},{"text":"Concurrent service","isCorrect":false,"rationale":"'Concurrent service' is incorrect. The correct answer is 'Maximum 40 years even if total exceeds'. Under the three-fold rule, the maximum duration is not more than three times the most severe penalty but shall not exceed 40 years. Review: Criminal Law Book I.","is_correct":false},{"text":"No maximum","isCorrect":false,"rationale":"'No maximum' is incorrect. The correct answer is 'Maximum 40 years even if total exceeds'. Under the three-fold rule, the maximum duration is not more than three times the most severe penalty but shall not exceed 40 years. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Maximum 40 years even if total exceeds","isCorrect":true,"rationale":"Under the three-fold rule, the maximum duration is not more than three times the most severe penalty but shall not exceed 40 years.","is_correct":true},{"text":"Maximum is twice the most severe penalty","is_correct":false,"rationale":"The limit is three times, not twice, the most severe penalty, and never more than 40 years (Art. 70)."},{"text":"All penalties served at the same time","is_correct":false,"rationale":"Simultaneous service applies only where the nature of the penalties allows it; the three-fold rule limits successive service."},{"text":"Maximum 30 years for any number of crimes","is_correct":false,"rationale":"The cap under Art. 70 is 40 years, not 30."}]$opt$::jsonb),
  ('cj_082', $opt$[{"text":"Act is wrong but offender exempt","isCorrect":true,"rationale":"Absolutory causes exempt the actor from punishment although the act is a crime.","is_correct":true},{"text":"Act is not wrong","isCorrect":false,"rationale":"'Act is not wrong' is incorrect. The correct answer is 'Act is wrong but offender exempt'. Absolutory causes exempt the actor from punishment although the act is a crime. Review: Criminal Law Book I.","is_correct":false},{"text":"Heavier penalty","isCorrect":false,"rationale":"'Heavier penalty' is incorrect. The correct answer is 'Act is wrong but offender exempt'. Absolutory causes exempt the actor from punishment although the act is a crime. Review: Criminal Law Book I.","is_correct":false},{"text":"No exemption","isCorrect":false,"rationale":"'No exemption' is incorrect. The correct answer is 'Act is wrong but offender exempt'. Absolutory causes exempt the actor from punishment although the act is a crime. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Act is wrong but offender exempt","isCorrect":true,"rationale":"Absolutory causes exempt the actor from punishment although the act is a crime.","is_correct":true},{"text":"Act is lawful so there is no crime","is_correct":false,"rationale":"That describes a justifying circumstance. With an absolutory cause the act is still wrong, but no penalty is imposed."},{"text":"Penalty is lowered by one degree","is_correct":false,"rationale":"That is the effect of a privileged mitigating circumstance."},{"text":"Penalty is raised to the maximum","is_correct":false,"rationale":"That is the effect of an aggravating circumstance."}]$opt$::jsonb),
  ('cj_083', $opt$[{"text":"Act would be crime if not for inherent impossibility","isCorrect":true,"rationale":"An impossible crime is committed when the act would be a crime but is inherently impossible of accomplishment.","is_correct":true},{"text":"Completed crime","isCorrect":false,"rationale":"'Completed crime' is incorrect. The correct answer is 'Act would be crime if not for inherent impossibility'. An impossible crime is committed when the act would be a crime but is inherently impossible of accomplishment. Review: Criminal Law Book I.","is_correct":false},{"text":"No criminal liability","isCorrect":false,"rationale":"'No criminal liability' is incorrect. The correct answer is 'Act would be crime if not for inherent impossibility'. An impossible crime is committed when the act would be a crime but is inherently impossible of accomplishment. Review: Criminal Law Book I.","is_correct":false},{"text":"Civil liability only","isCorrect":false,"rationale":"'Civil liability only' is incorrect. The correct answer is 'Act would be crime if not for inherent impossibility'. An impossible crime is committed when the act would be a crime but is inherently impossible of accomplishment. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Act would be crime if not for inherent impossibility","isCorrect":true,"rationale":"An impossible crime is committed when the act would be a crime but is inherently impossible of accomplishment.","is_correct":true},{"text":"Act stopped by outside causes before completion","is_correct":false,"rationale":"That is an attempted felony."},{"text":"Act completed but its result did not happen","is_correct":false,"rationale":"That is a frustrated felony."},{"text":"Act committed by a person exempt from liability","is_correct":false,"rationale":"That involves an exempting circumstance, not an impossible crime."}]$opt$::jsonb),
  ('cj_096', $opt$[{"text":"Conspiracy inferred from coordinated acts","isCorrect":true,"rationale":"Implied conspiracy is inferred from the coordinated acts of the accused showing common purpose.","is_correct":true},{"text":"Express agreement needed","isCorrect":false,"rationale":"'Express agreement needed' is incorrect. The correct answer is 'Conspiracy inferred from coordinated acts'. Implied conspiracy is inferred from the coordinated acts of the accused showing common purpose. Review: Criminal Law Book I.","is_correct":false},{"text":"No conspiracy exists","isCorrect":false,"rationale":"'No conspiracy exists' is incorrect. The correct answer is 'Conspiracy inferred from coordinated acts'. Implied conspiracy is inferred from the coordinated acts of the accused showing common purpose. Review: Criminal Law Book I.","is_correct":false},{"text":"Only written agreement","isCorrect":false,"rationale":"'Only written agreement' is incorrect. The correct answer is 'Conspiracy inferred from coordinated acts'. Implied conspiracy is inferred from the coordinated acts of the accused showing common purpose. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Conspiracy inferred from coordinated acts","isCorrect":true,"rationale":"Implied conspiracy is inferred from the coordinated acts of the accused showing common purpose.","is_correct":true},{"text":"Conspiracy proven only by a written agreement","is_correct":false,"rationale":"Conspiracy need not be written. Implied conspiracy is shown by the coordinated acts of the accused."},{"text":"Conspiracy proven by a prior express agreement","is_correct":false,"rationale":"That is express conspiracy; implied conspiracy is inferred without proof of a prior agreement."},{"text":"Proposal to commit a felony to another person","is_correct":false,"rationale":"That is proposal (Art. 8), not implied conspiracy."}]$opt$::jsonb),
  ('cj_097', $opt$[{"text":"Lesser crime absorbed in graver offense","isCorrect":true,"rationale":"Absorption means a lesser crime is absorbed when it is a necessary means to commit the graver offense.","is_correct":true},{"text":"All crimes punished separately","isCorrect":false,"rationale":"'All crimes punished separately' is incorrect. The correct answer is 'Lesser crime absorbed in graver offense'. Absorption means a lesser crime is absorbed when it is a necessary means to commit the graver offense. Review: Criminal Law Book I.","is_correct":false},{"text":"No absorption","isCorrect":false,"rationale":"'No absorption' is incorrect. The correct answer is 'Lesser crime absorbed in graver offense'. Absorption means a lesser crime is absorbed when it is a necessary means to commit the graver offense. Review: Criminal Law Book I.","is_correct":false},{"text":"Only in civil cases","isCorrect":false,"rationale":"'Only in civil cases' is incorrect. The correct answer is 'Lesser crime absorbed in graver offense'. Absorption means a lesser crime is absorbed when it is a necessary means to commit the graver offense. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Lesser crime absorbed in graver offense","isCorrect":true,"rationale":"Absorption means a lesser crime is absorbed when it is a necessary means to commit the graver offense.","is_correct":true},{"text":"Each crime punished with its own penalty","is_correct":false,"rationale":"That is the rule for separate crimes, the opposite of absorption."},{"text":"Single act producing two grave felonies","is_correct":false,"rationale":"That is a compound crime (Art. 48), punished with the penalty for the most serious crime."},{"text":"Graver penalty imposed in its maximum period","is_correct":false,"rationale":"That is the penalty rule for complex crimes, not absorption."}]$opt$::jsonb),
  ('cj_098', $opt$[{"text":"Difference between charge and proof","isCorrect":true,"rationale":"Variance occurs when there is a material difference between the allegations and proof.","is_correct":true},{"text":"Identical charge and proof","isCorrect":false,"rationale":"'Identical charge and proof' is incorrect. The correct answer is 'Difference between charge and proof'. Variance occurs when there is a material difference between the allegations and proof. Review: Criminal Law Book I.","is_correct":false},{"text":"No charge needed","isCorrect":false,"rationale":"'No charge needed' is incorrect. The correct answer is 'Difference between charge and proof'. Variance occurs when there is a material difference between the allegations and proof. Review: Criminal Law Book I.","is_correct":false},{"text":"Only for civil cases","isCorrect":false,"rationale":"'Only for civil cases' is incorrect. The correct answer is 'Difference between charge and proof'. Variance occurs when there is a material difference between the allegations and proof. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Difference between charge and proof","isCorrect":true,"rationale":"Variance occurs when there is a material difference between the allegations and proof.","is_correct":true},{"text":"Difference between two witnesses' accounts","is_correct":false,"rationale":"That is an inconsistency in testimony, not variance."},{"text":"Difference between trial and appeal rulings","is_correct":false,"rationale":"That is a reversal or modification on appeal, not variance."},{"text":"Change of the charge before arraignment","is_correct":false,"rationale":"That is amendment of the information (Rule 110, Sec. 14)."}]$opt$::jsonb),
  ('cj_105', $opt$[{"text":"Reclusion perpetua if death results","isCorrect":true,"rationale":"Under RA 11053, hazing resulting in death is punishable by reclusion perpetua.","is_correct":true},{"text":"Fine only","isCorrect":false,"rationale":"'Fine only' is incorrect. The correct answer is 'Reclusion perpetua if death results'. Under RA 11053, hazing resulting in death is punishable by reclusion perpetua. Review: Criminal Law Book I.","is_correct":false},{"text":"Probation always","isCorrect":false,"rationale":"'Probation always' is incorrect. The correct answer is 'Reclusion perpetua if death results'. Under RA 11053, hazing resulting in death is punishable by reclusion perpetua. Review: Criminal Law Book I.","is_correct":false},{"text":"Community service","isCorrect":false,"rationale":"'Community service' is incorrect. The correct answer is 'Reclusion perpetua if death results'. Under RA 11053, hazing resulting in death is punishable by reclusion perpetua. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Reclusion perpetua if death results","isCorrect":true,"rationale":"Under RA 11053, hazing resulting in death is punishable by reclusion perpetua.","is_correct":true},{"text":"Prision mayor if death results","is_correct":false,"rationale":"Under RA 11053 (2018), the penalty when death results is reclusion perpetua, not prision mayor."},{"text":"Reclusion temporal if death results","is_correct":false,"rationale":"Under RA 11053 (2018), the penalty when death results is reclusion perpetua, not reclusion temporal."},{"text":"Death penalty if death results","is_correct":false,"rationale":"The death penalty was abolished by RA 9346 (2006); RA 11053 imposes reclusion perpetua."}]$opt$::jsonb),
  ('cj_120', $opt$[{"text":"Cause that absolves offender from liability","isCorrect":true,"rationale":"Absolutory causes exempt from criminal liability similar to justifying circumstances.","is_correct":true},{"text":"Increases penalty","isCorrect":false,"rationale":"'Increases penalty' is incorrect. The correct answer is 'Cause that absolves offender from liability'. Absolutory causes exempt from criminal liability similar to justifying circumstances. Review: Criminal Law Book I.","is_correct":false},{"text":"No effect","isCorrect":false,"rationale":"'No effect' is incorrect. The correct answer is 'Cause that absolves offender from liability'. Absolutory causes exempt from criminal liability similar to justifying circumstances. Review: Criminal Law Book I.","is_correct":false},{"text":"Justifying only","isCorrect":false,"rationale":"'Justifying only' is incorrect. The correct answer is 'Cause that absolves offender from liability'. Absolutory causes exempt from criminal liability similar to justifying circumstances. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Cause that absolves offender from liability","isCorrect":true,"rationale":"Absolutory causes exempt from criminal liability similar to justifying circumstances.","is_correct":true},{"text":"Cause that makes the act lawful","is_correct":false,"rationale":"That is a justifying circumstance. With an absolutory cause the act remains a crime, but the offender is not punished."},{"text":"Cause that lowers the penalty by degrees","is_correct":false,"rationale":"That is a privileged mitigating circumstance."},{"text":"Cause that raises the penalty to its maximum","is_correct":false,"rationale":"That is an aggravating circumstance."}]$opt$::jsonb),
  ('cj_121', $opt$[{"text":"Instigation is absolutory, entrapment is not","isCorrect":true,"rationale":"Instigation by public officer absolves liability; entrapment does not.","is_correct":true},{"text":"Same thing","isCorrect":false,"rationale":"'Same thing' is incorrect. The correct answer is 'Instigation is absolutory, entrapment is not'. Instigation by public officer absolves liability; entrapment does not. Review: Criminal Law Book I.","is_correct":false},{"text":"Both absolutory","isCorrect":false,"rationale":"'Both absolutory' is incorrect. The correct answer is 'Instigation is absolutory, entrapment is not'. Instigation by public officer absolves liability; entrapment does not. Review: Criminal Law Book I.","is_correct":false},{"text":"Neither matters","isCorrect":false,"rationale":"'Neither matters' is incorrect. The correct answer is 'Instigation is absolutory, entrapment is not'. Instigation by public officer absolves liability; entrapment does not. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Instigation is absolutory, entrapment is not","isCorrect":true,"rationale":"Instigation by public officer absolves liability; entrapment does not.","is_correct":true},{"text":"Entrapment is absolutory, instigation is not","is_correct":false,"rationale":"Reversed: instigation induces the crime and is absolutory; entrapment only catches an offender who was already willing."},{"text":"Both are absolutory causes for the accused","is_correct":false,"rationale":"Only instigation is absolutory."},{"text":"Both are aggravating against the accused","is_correct":false,"rationale":"Neither is aggravating. Entrapment is allowed, while instigation frees the accused."}]$opt$::jsonb),
  ('cj_122', $opt$[{"text":"Doubt resolved in favor of accused","isCorrect":true,"rationale":"Pro reo means that in case of doubt, the interpretation should favor the accused.","is_correct":true},{"text":"Doubt resolved in favor of prosecution","isCorrect":false,"rationale":"'Doubt resolved in favor of prosecution' is incorrect. The correct answer is 'Doubt resolved in favor of accused'. Pro reo means that in case of doubt, the interpretation should favor the accused. Review: Criminal Law Book I.","is_correct":false},{"text":"Strict interpretation","isCorrect":false,"rationale":"'Strict interpretation' is incorrect. The correct answer is 'Doubt resolved in favor of accused'. Pro reo means that in case of doubt, the interpretation should favor the accused. Review: Criminal Law Book I.","is_correct":false},{"text":"Literal interpretation","isCorrect":false,"rationale":"'Literal interpretation' is incorrect. The correct answer is 'Doubt resolved in favor of accused'. Pro reo means that in case of doubt, the interpretation should favor the accused. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Doubt resolved in favor of accused","isCorrect":true,"rationale":"Pro reo means that in case of doubt, the interpretation should favor the accused.","is_correct":true},{"text":"Doubt resolved in favor of prosecution","is_correct":false,"rationale":"Reversed: under pro reo, doubts in penal laws are resolved in favor of the accused."},{"text":"Law applied exactly as written always","is_correct":false,"rationale":"That is literal interpretation, not the pro reo principle."},{"text":"Penal laws applied retroactively always","is_correct":false,"rationale":"Penal laws apply retroactively only when favorable to the accused (Art. 22); not always."}]$opt$::jsonb),
  ('cj_125', $opt$[{"text":"Result beyond intent","isCorrect":true,"rationale":"Praeter intentionem means the result is beyond the intent of the offender, a mitigating circumstance.","is_correct":true},{"text":"With clear intent","isCorrect":false,"rationale":"'With clear intent' is incorrect. The correct answer is 'Result beyond intent'. Praeter intentionem means the result is beyond the intent of the offender, a mitigating circumstance. Review: Criminal Law Book I.","is_correct":false},{"text":"No intent","isCorrect":false,"rationale":"'No intent' is incorrect. The correct answer is 'Result beyond intent'. Praeter intentionem means the result is beyond the intent of the offender, a mitigating circumstance. Review: Criminal Law Book I.","is_correct":false},{"text":"Self-defense","isCorrect":false,"rationale":"'Self-defense' is incorrect. The correct answer is 'Result beyond intent'. Praeter intentionem means the result is beyond the intent of the offender, a mitigating circumstance. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Result beyond intent","isCorrect":true,"rationale":"Praeter intentionem means the result is beyond the intent of the offender, a mitigating circumstance.","is_correct":true},{"text":"Mistake in the blow","is_correct":false,"rationale":"That is aberratio ictus."},{"text":"Mistake in identity","is_correct":false,"rationale":"That is error in personae."},{"text":"Act without any intent","is_correct":false,"rationale":"Felonies by culpa have no intent at all. Praeter intentionem means the result went beyond what was intended."}]$opt$::jsonb),
  ('cj_135', $opt$[{"text":"Committing felony while serving sentence","isCorrect":true,"rationale":"Quasi-recidivism is committing another felony while serving sentence for a previous crime.","is_correct":true},{"text":"First offense","isCorrect":false,"rationale":"'First offense' is incorrect. The correct answer is 'Committing felony while serving sentence'. Quasi-recidivism is committing another felony while serving sentence for a previous crime. Review: Criminal Law Book I.","is_correct":false},{"text":"Attempted crime","isCorrect":false,"rationale":"'Attempted crime' is incorrect. The correct answer is 'Committing felony while serving sentence'. Quasi-recidivism is committing another felony while serving sentence for a previous crime. Review: Criminal Law Book I.","is_correct":false},{"text":"Minor violation","isCorrect":false,"rationale":"'Minor violation' is incorrect. The correct answer is 'Committing felony while serving sentence'. Quasi-recidivism is committing another felony while serving sentence for a previous crime. Review: Criminal Law Book I.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Committing felony while serving sentence","isCorrect":true,"rationale":"Quasi-recidivism is committing another felony while serving sentence for a previous crime.","is_correct":true},{"text":"Second conviction under the same title of the Code","is_correct":false,"rationale":"That is recidivism (Art. 14(9))."},{"text":"Third conviction for theft within ten years","is_correct":false,"rationale":"That is habitual delinquency (Art. 62)."},{"text":"Committing a felony while out on bail","is_correct":false,"rationale":"Being on bail is not serving a sentence. Quasi-recidivism needs a final conviction, then a new felony before or while serving it."}]$opt$::jsonb),
  ('cj_047', $opt$[{"text":"All acts done but crime not produced for causes independent of will","isCorrect":true,"rationale":"Frustrated felony: offender performs all acts of execution but crime is not produced due to causes independent of his will.","is_correct":true},{"text":"Completed crime","isCorrect":false,"rationale":"'Completed crime' is incorrect. The correct answer is 'All acts done but crime not produced for causes independent of will'. Frustrated felony: offender performs all acts of execution but crime is not produced due to causes independent of his will. Review: Criminal Law Book II.","is_correct":false},{"text":"Attempted crime","isCorrect":false,"rationale":"'Attempted crime' is incorrect. The correct answer is 'All acts done but crime not produced for causes independent of will'. Frustrated felony: offender performs all acts of execution but crime is not produced due to causes independent of his will. Review: Criminal Law Book II.","is_correct":false},{"text":"Impossible crime","isCorrect":false,"rationale":"'Impossible crime' is incorrect. The correct answer is 'All acts done but crime not produced for causes independent of will'. Frustrated felony: offender performs all acts of execution but crime is not produced due to causes independent of his will. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"All acts done but crime not produced for causes independent of will","isCorrect":true,"rationale":"Frustrated felony: offender performs all acts of execution but crime is not produced due to causes independent of his will.","is_correct":true},{"text":"Overt acts begun but not all acts of execution performed","is_correct":false,"rationale":"That is the attempted stage."},{"text":"All acts done and every element of the felony accomplished","is_correct":false,"rationale":"That is the consummated stage."},{"text":"Acts that can never produce the crime because of impossibility","is_correct":false,"rationale":"That is an impossible crime."}]$opt$::jsonb),
  ('cj_048', $opt$[{"text":"Overt acts started but not all acts of execution done","isCorrect":true,"rationale":"Attempted felony: offender commences directly by overt acts but does not perform all acts of execution.","is_correct":true},{"text":"Completed crime","isCorrect":false,"rationale":"'Completed crime' is incorrect. The correct answer is 'Overt acts started but not all acts of execution done'. Attempted felony: offender commences directly by overt acts but does not perform all acts of execution. Review: Criminal Law Book II.","is_correct":false},{"text":"Frustrated crime","isCorrect":false,"rationale":"'Frustrated crime' is incorrect. The correct answer is 'Overt acts started but not all acts of execution done'. Attempted felony: offender commences directly by overt acts but does not perform all acts of execution. Review: Criminal Law Book II.","is_correct":false},{"text":"Impossible crime","isCorrect":false,"rationale":"'Impossible crime' is incorrect. The correct answer is 'Overt acts started but not all acts of execution done'. Attempted felony: offender commences directly by overt acts but does not perform all acts of execution. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Overt acts started but not all acts of execution done","isCorrect":true,"rationale":"Attempted felony: offender commences directly by overt acts but does not perform all acts of execution.","is_correct":true},{"text":"All acts of execution done but the result did not follow","is_correct":false,"rationale":"That is the frustrated stage."},{"text":"Preparatory acts done but no overt act begun yet","is_correct":false,"rationale":"Preparatory acts are generally not punishable; the attempted stage begins with overt acts."},{"text":"Acts done that could never produce the felony","is_correct":false,"rationale":"That is an impossible crime."}]$opt$::jsonb),
  ('cj_084', $opt$[{"text":"Other crimes absorbed in special complex crime","isCorrect":true,"rationale":"In robbery with homicide, other crimes like rape committed on the occasion are absorbed.","is_correct":true},{"text":"Separate punishment for each","isCorrect":false,"rationale":"'Separate punishment for each' is incorrect. The correct answer is 'Other crimes absorbed in special complex crime'. In robbery with homicide, other crimes like rape committed on the occasion are absorbed. Review: Criminal Law Book II.","is_correct":false},{"text":"Lighter penalty","isCorrect":false,"rationale":"'Lighter penalty' is incorrect. The correct answer is 'Other crimes absorbed in special complex crime'. In robbery with homicide, other crimes like rape committed on the occasion are absorbed. Review: Criminal Law Book II.","is_correct":false},{"text":"No absorption","isCorrect":false,"rationale":"'No absorption' is incorrect. The correct answer is 'Other crimes absorbed in special complex crime'. In robbery with homicide, other crimes like rape committed on the occasion are absorbed. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Other crimes absorbed in special complex crime","isCorrect":true,"rationale":"In robbery with homicide, other crimes like rape committed on the occasion are absorbed.","is_correct":true},{"text":"Homicide and robbery punished separately","is_correct":false,"rationale":"Robbery with homicide is a special complex crime with a single penalty."},{"text":"Robbery absorbed as a mere aggravating factor","is_correct":false,"rationale":"Robbery is not reduced to an aggravating circumstance; both are joined into one special complex crime."},{"text":"Graver penalty applied in its maximum period","is_correct":false,"rationale":"That is the rule for ordinary complex crimes under Art. 48."}]$opt$::jsonb),
  ('cj_085', $opt$[{"text":"Accumulating ill-gotten wealth of at least P50 million","isCorrect":true,"rationale":"Plunder is committed by a public officer who accumulates ill-gotten wealth of at least P50 million.","is_correct":true},{"text":"Simple theft","isCorrect":false,"rationale":"'Simple theft' is incorrect. The correct answer is 'Accumulating ill-gotten wealth of at least P50 million'. Plunder is committed by a public officer who accumulates ill-gotten wealth of at least P50 million. Review: Criminal Law Book II.","is_correct":false},{"text":"Estafa","isCorrect":false,"rationale":"'Estafa' is incorrect. The correct answer is 'Accumulating ill-gotten wealth of at least P50 million'. Plunder is committed by a public officer who accumulates ill-gotten wealth of at least P50 million. Review: Criminal Law Book II.","is_correct":false},{"text":"Robbery","isCorrect":false,"rationale":"'Robbery' is incorrect. The correct answer is 'Accumulating ill-gotten wealth of at least P50 million'. Plunder is committed by a public officer who accumulates ill-gotten wealth of at least P50 million. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Accumulating ill-gotten wealth of at least P50 million","isCorrect":true,"rationale":"Plunder is committed by a public officer who accumulates ill-gotten wealth of at least P50 million.","is_correct":true},{"text":"Accumulating ill-gotten wealth of at least P75 million","is_correct":false,"rationale":"RA 7080 first set P75 million, but RA 7659 lowered the threshold to P50 million."},{"text":"Taking public funds of any amount for personal use","is_correct":false,"rationale":"That describes malversation (Art. 217), which has no minimum amount."},{"text":"Receiving gifts in exchange for official favors","is_correct":false,"rationale":"That is bribery (Arts. 210-211), not plunder."}]$opt$::jsonb),
  ('cj_099', $opt$[{"text":"Circumstances that make homicide murder","isCorrect":true,"rationale":"Qualifying circumstances like treachery and premeditation elevate homicide to murder.","is_correct":true},{"text":"Mitigating factors","isCorrect":false,"rationale":"'Mitigating factors' is incorrect. The correct answer is 'Circumstances that make homicide murder'. Qualifying circumstances like treachery and premeditation elevate homicide to murder. Review: Criminal Law Book II.","is_correct":false},{"text":"Exempting factors","isCorrect":false,"rationale":"'Exempting factors' is incorrect. The correct answer is 'Circumstances that make homicide murder'. Qualifying circumstances like treachery and premeditation elevate homicide to murder. Review: Criminal Law Book II.","is_correct":false},{"text":"Absolutory causes","isCorrect":false,"rationale":"'Absolutory causes' is incorrect. The correct answer is 'Circumstances that make homicide murder'. Qualifying circumstances like treachery and premeditation elevate homicide to murder. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Circumstances that make homicide murder","isCorrect":true,"rationale":"Qualifying circumstances like treachery and premeditation elevate homicide to murder.","is_correct":true},{"text":"Circumstances that lower the penalty","is_correct":false,"rationale":"Those are mitigating circumstances."},{"text":"Circumstances that free the accused","is_correct":false,"rationale":"Those are exempting circumstances."},{"text":"Circumstances that make the killing lawful","is_correct":false,"rationale":"Those are justifying circumstances."}]$opt$::jsonb),
  ('cj_117', $opt$[{"text":"Rising publicly to attain certain objectives","isCorrect":true,"rationale":"Sedition is rising publicly and tumultuously to prevent law execution.","is_correct":true},{"text":"Individual crime","isCorrect":false,"rationale":"'Individual crime' is incorrect. The correct answer is 'Rising publicly to attain certain objectives'. Sedition is rising publicly and tumultuously to prevent law execution. Review: Criminal Law Book II.","is_correct":false},{"text":"Property crime","isCorrect":false,"rationale":"'Property crime' is incorrect. The correct answer is 'Rising publicly to attain certain objectives'. Sedition is rising publicly and tumultuously to prevent law execution. Review: Criminal Law Book II.","is_correct":false},{"text":"Traffic violation","isCorrect":false,"rationale":"'Traffic violation' is incorrect. The correct answer is 'Rising publicly to attain certain objectives'. Sedition is rising publicly and tumultuously to prevent law execution. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Rising publicly to attain certain objectives","isCorrect":true,"rationale":"Sedition is rising publicly and tumultuously to prevent law execution.","is_correct":true},{"text":"Rising publicly in arms to remove allegiance","is_correct":false,"rationale":"That is rebellion (Art. 134)."},{"text":"Seizing power suddenly by persons in authority","is_correct":false,"rationale":"That is coup d'etat (Art. 134-A)."},{"text":"Inciting others to rebel through speeches","is_correct":false,"rationale":"That is inciting to rebellion (Art. 138)."}]$opt$::jsonb),
  ('cj_118', $opt$[{"text":"Armed uprising against government","isCorrect":true,"rationale":"Rebellion is taking up arms against the government.","is_correct":true},{"text":"Peaceful protest","isCorrect":false,"rationale":"'Peaceful protest' is incorrect. The correct answer is 'Armed uprising against government'. Rebellion is taking up arms against the government. Review: Criminal Law Book II.","is_correct":false},{"text":"Property crime","isCorrect":false,"rationale":"'Property crime' is incorrect. The correct answer is 'Armed uprising against government'. Rebellion is taking up arms against the government. Review: Criminal Law Book II.","is_correct":false},{"text":"Personal crime","isCorrect":false,"rationale":"'Personal crime' is incorrect. The correct answer is 'Armed uprising against government'. Rebellion is taking up arms against the government. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Armed uprising against government","isCorrect":true,"rationale":"Rebellion is taking up arms against the government.","is_correct":true},{"text":"Public uprising to prevent a law's execution","is_correct":false,"rationale":"That is one objective of sedition (Art. 139), not rebellion."},{"text":"Swift attack on military installations by officers","is_correct":false,"rationale":"That is coup d'etat (Art. 134-A)."},{"text":"Levying war on behalf of a foreign enemy","is_correct":false,"rationale":"That is treason, which requires allegiance to the Philippines and a foreign enemy."}]$opt$::jsonb),
  ('cj_119', $opt$[{"text":"Levying war or adhering to enemies","isCorrect":true,"rationale":"Treason is levying war against Philippines or adhering to its enemies.","is_correct":true},{"text":"Regular crime","isCorrect":false,"rationale":"'Regular crime' is incorrect. The correct answer is 'Levying war or adhering to enemies'. Treason is levying war against Philippines or adhering to its enemies. Review: Criminal Law Book II.","is_correct":false},{"text":"Property crime","isCorrect":false,"rationale":"'Property crime' is incorrect. The correct answer is 'Levying war or adhering to enemies'. Treason is levying war against Philippines or adhering to its enemies. Review: Criminal Law Book II.","is_correct":false},{"text":"Personal crime","isCorrect":false,"rationale":"'Personal crime' is incorrect. The correct answer is 'Levying war or adhering to enemies'. Treason is levying war against Philippines or adhering to its enemies. Review: Criminal Law Book II.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Levying war or adhering to enemies","isCorrect":true,"rationale":"Treason is levying war against Philippines or adhering to its enemies.","is_correct":true},{"text":"Armed uprising to overthrow the government","is_correct":false,"rationale":"That is rebellion."},{"text":"Revealing defense secrets to a foreign power","is_correct":false,"rationale":"That is espionage (Art. 117 and Commonwealth Act 616)."},{"text":"Inciting others to war against the state","is_correct":false,"rationale":"That is not treason; treason requires levying war or adhering to the enemy, giving aid or comfort."}]$opt$::jsonb),
  ('cj_101', $opt$[{"text":"Right to counsel and silence during custodial investigation","isCorrect":true,"rationale":"Miranda rights include the right to remain silent and to have counsel during custodial investigation.","is_correct":true},{"text":"No rights during arrest","isCorrect":false,"rationale":"'No rights during arrest' is incorrect. The correct answer is 'Right to counsel and silence during custodial investigation'. Miranda rights include the right to remain silent and to have counsel during custodial investigation. Review: Criminal Procedure.","is_correct":false},{"text":"Rights only in court","isCorrect":false,"rationale":"'Rights only in court' is incorrect. The correct answer is 'Right to counsel and silence during custodial investigation'. Miranda rights include the right to remain silent and to have counsel during custodial investigation. Review: Criminal Procedure.","is_correct":false},{"text":"Only for serious crimes","isCorrect":false,"rationale":"'Only for serious crimes' is incorrect. The correct answer is 'Right to counsel and silence during custodial investigation'. Miranda rights include the right to remain silent and to have counsel during custodial investigation. Review: Criminal Procedure.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Right to counsel and silence during custodial investigation","isCorrect":true,"rationale":"Miranda rights include the right to remain silent and to have counsel during custodial investigation.","is_correct":true},{"text":"Right to bail before conviction for any offense","is_correct":false,"rationale":"Bail is a separate constitutional right, and not for every offense; it is not the Miranda doctrine."},{"text":"Right to confront witnesses during the trial","is_correct":false,"rationale":"That is the right of confrontation."},{"text":"Right to a speedy trial after the arraignment","is_correct":false,"rationale":"That is the right to a speedy trial."}]$opt$::jsonb),
  ('qb_cj_005', $opt$[{"text":"Evidence obtained from plants is inadmissible","isCorrect":false,"rationale":"'Evidence obtained from plants is inadmissible' is incorrect. The correct answer is 'Evidence derived from illegally obtained evidence is inadmissible'. The fruit of the poisonous tree doctrine excludes evidence obtained as a result of illegal searches or other constitutional violations. Review: Evidence Law.","is_correct":false},{"text":"Evidence derived from illegally obtained evidence is inadmissible","isCorrect":true,"rationale":"The fruit of the poisonous tree doctrine excludes evidence obtained as a result of illegal searches or other constitutional violations.","is_correct":true},{"text":"Circumstantial evidence is always inadmissible","isCorrect":false,"rationale":"'Circumstantial evidence is always inadmissible' is incorrect. The correct answer is 'Evidence derived from illegally obtained evidence is inadmissible'. The fruit of the poisonous tree doctrine excludes evidence obtained as a result of illegal searches or other constitutional violations. Review: Evidence Law.","is_correct":false},{"text":"Hearsay evidence is admissible","isCorrect":false,"rationale":"'Hearsay evidence is admissible' is incorrect. The correct answer is 'Evidence derived from illegally obtained evidence is inadmissible'. The fruit of the poisonous tree doctrine excludes evidence obtained as a result of illegal searches or other constitutional violations. Review: Evidence Law.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Evidence seized with a valid warrant is always admissible","is_correct":false,"rationale":"Not the doctrine. The fruit of the poisonous tree concerns evidence derived from an illegal search or seizure."},{"text":"Evidence derived from illegally obtained evidence is inadmissible","isCorrect":true,"rationale":"The fruit of the poisonous tree doctrine excludes evidence obtained as a result of illegal searches or other constitutional violations.","is_correct":true},{"text":"Confessions taken without counsel may still be used later","is_correct":false,"rationale":"The opposite: such confessions are inadmissible (1987 Constitution, Art. III, Sec. 12)."},{"text":"Evidence found by private persons is always inadmissible","is_correct":false,"rationale":"Wrong: the exclusionary rule binds the State, not private persons (People v. Marti)."}]$opt$::jsonb),
  ('cj_023', $opt$[{"text":"Mental age of 2-7 years","isCorrect":true,"rationale":"An imbecile has a mental age of 2-7 years, while an idiot has a mental age below 2 years.","is_correct":true},{"text":"Mental age below 2 years","isCorrect":false,"rationale":"'Mental age below 2 years' is incorrect. The correct answer is 'Mental age of 2-7 years'. An imbecile has a mental age of 2-7 years, while an idiot has a mental age below 2 years. Review: Exempting Circumstances.","is_correct":false},{"text":"Temporary insanity","isCorrect":false,"rationale":"'Temporary insanity' is incorrect. The correct answer is 'Mental age of 2-7 years'. An imbecile has a mental age of 2-7 years, while an idiot has a mental age below 2 years. Review: Exempting Circumstances.","is_correct":false},{"text":"Drug-induced state","isCorrect":false,"rationale":"'Drug-induced state' is incorrect. The correct answer is 'Mental age of 2-7 years'. An imbecile has a mental age of 2-7 years, while an idiot has a mental age below 2 years. Review: Exempting Circumstances.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Mental age of 2-7 years","isCorrect":true,"rationale":"An imbecile has a mental age of 2-7 years, while an idiot has a mental age below 2 years.","is_correct":true},{"text":"Mental age below 2 years","is_correct":false,"rationale":"That is idiocy, a more severe level."},{"text":"Mental age of 7-12 years","is_correct":false,"rationale":"That is moronity (feeblemindedness), which is not an exempting circumstance."},{"text":"Mental age of 12-15 years","is_correct":false,"rationale":"A mental age above 7 is not imbecility and is not exempting."}]$opt$::jsonb),
  ('cj_019', $opt$[{"text":"Unlawful aggression, Reasonable necessity, Lack of provocation","isCorrect":true,"rationale":"Self-defense requires: (1) unlawful aggression, (2) reasonable necessity of means, and (3) lack of sufficient provocation.","is_correct":true},{"text":"Only unlawful aggression","isCorrect":false,"rationale":"'Only unlawful aggression' is incorrect. The correct answer is 'Unlawful aggression, Reasonable necessity, Lack of provocation'. Self-defense requires: (1) unlawful aggression, (2) reasonable necessity of means, and (3) lack of sufficient provocation. Review: Justifying Circumstances.","is_correct":false},{"text":"Only reasonable force","isCorrect":false,"rationale":"'Only reasonable force' is incorrect. The correct answer is 'Unlawful aggression, Reasonable necessity, Lack of provocation'. Self-defense requires: (1) unlawful aggression, (2) reasonable necessity of means, and (3) lack of sufficient provocation. Review: Justifying Circumstances.","is_correct":false},{"text":"Only lack of provocation","isCorrect":false,"rationale":"'Only lack of provocation' is incorrect. The correct answer is 'Unlawful aggression, Reasonable necessity, Lack of provocation'. Self-defense requires: (1) unlawful aggression, (2) reasonable necessity of means, and (3) lack of sufficient provocation. Review: Justifying Circumstances.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Unlawful aggression, Reasonable necessity, Lack of provocation","isCorrect":true,"rationale":"Self-defense requires: (1) unlawful aggression, (2) reasonable necessity of means, and (3) lack of sufficient provocation.","is_correct":true},{"text":"Unlawful aggression, Reasonable necessity, Relationship to victim","is_correct":false,"rationale":"Relationship matters in defense of relatives, not in self-defense."},{"text":"Imminent danger, Equal weapons, Lack of provocation","is_correct":false,"rationale":"Equal weapons are not required; the means need only be reasonably necessary."},{"text":"Unlawful aggression, Actual injury, Lack of provocation","is_correct":false,"rationale":"The defender need not be injured first; the second element is reasonable necessity of the means."}]$opt$::jsonb),
  ('qb_cj_008', $opt$[{"text":"Evidence obtained by private individuals is admissible","isCorrect":true,"rationale":"People v. Marti held that constitutional protection against unreasonable searches applies only to government action, not private individuals.","is_correct":true},{"text":"All warrantless searches are invalid","isCorrect":false,"rationale":"'All warrantless searches are invalid' is incorrect. The correct answer is 'Evidence obtained by private individuals is admissible'. People v. Marti held that constitutional protection against unreasonable searches applies only to government action, not private individuals. Review: Landmark Cases.","is_correct":false},{"text":"Miranda rights are absolute","isCorrect":false,"rationale":"'Miranda rights are absolute' is incorrect. The correct answer is 'Evidence obtained by private individuals is admissible'. People v. Marti held that constitutional protection against unreasonable searches applies only to government action, not private individuals. Review: Landmark Cases.","is_correct":false},{"text":"Confessions are always inadmissible","isCorrect":false,"rationale":"'Confessions are always inadmissible' is incorrect. The correct answer is 'Evidence obtained by private individuals is admissible'. People v. Marti held that constitutional protection against unreasonable searches applies only to government action, not private individuals. Review: Landmark Cases.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Evidence obtained by private individuals is admissible","isCorrect":true,"rationale":"People v. Marti held that constitutional protection against unreasonable searches applies only to government action, not private individuals.","is_correct":true},{"text":"Evidence obtained by private individuals is inadmissible","is_correct":false,"rationale":"Reversed: Marti held that the Bill of Rights binds the State, so evidence found by private persons is admissible."},{"text":"Warrantless searches by police are always valid","is_correct":false,"rationale":"Marti did not hold that; the case concerned a search by a private forwarding company."},{"text":"Evidence from courier inspections needs a warrant","is_correct":false,"rationale":"The courier's own inspection in Marti needed no warrant because it was a private act."}]$opt$::jsonb),
  ('cj_024', $opt$[{"text":"Circumstances that reduce penalty by degrees","isCorrect":true,"rationale":"Privileged mitigating circumstances reduce the penalty by one or two degrees (e.g., minority, incomplete self-defense).","is_correct":true},{"text":"Ordinary circumstances","isCorrect":false,"rationale":"'Ordinary circumstances' is incorrect. The correct answer is 'Circumstances that reduce penalty by degrees'. Privileged mitigating circumstances reduce the penalty by one or two degrees (e.g., minority, incomplete self-defense). Review: Mitigating Circumstances.","is_correct":false},{"text":"Aggravating circumstances","isCorrect":false,"rationale":"'Aggravating circumstances' is incorrect. The correct answer is 'Circumstances that reduce penalty by degrees'. Privileged mitigating circumstances reduce the penalty by one or two degrees (e.g., minority, incomplete self-defense). Review: Mitigating Circumstances.","is_correct":false},{"text":"Alternative circumstances","isCorrect":false,"rationale":"'Alternative circumstances' is incorrect. The correct answer is 'Circumstances that reduce penalty by degrees'. Privileged mitigating circumstances reduce the penalty by one or two degrees (e.g., minority, incomplete self-defense). Review: Mitigating Circumstances.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Circumstances that reduce penalty by degrees","isCorrect":true,"rationale":"Privileged mitigating circumstances reduce the penalty by one or two degrees (e.g., minority, incomplete self-defense).","is_correct":true},{"text":"Circumstances that lower the penalty by period","is_correct":false,"rationale":"That is the effect of ordinary mitigating circumstances, which can be offset by aggravating ones."},{"text":"Circumstances that raise the penalty by degrees","is_correct":false,"rationale":"That would be aggravating; privileged mitigating circumstances lower the penalty."},{"text":"Circumstances that are either aggravating or mitigating","is_correct":false,"rationale":"Those are alternative circumstances (Art. 15)."}]$opt$::jsonb),
  ('cj_043', $opt$[{"text":"Evidence from illegal search is inadmissible","isCorrect":true,"rationale":"Evidence obtained as a result of an illegal search or seizure is inadmissible in court.","is_correct":true},{"text":"All evidence is admissible","isCorrect":false,"rationale":"'All evidence is admissible' is incorrect. The correct answer is 'Evidence from illegal search is inadmissible'. Evidence obtained as a result of an illegal search or seizure is inadmissible in court. Review: Rules of Evidence.","is_correct":false},{"text":"Only direct evidence allowed","isCorrect":false,"rationale":"'Only direct evidence allowed' is incorrect. The correct answer is 'Evidence from illegal search is inadmissible'. Evidence obtained as a result of an illegal search or seizure is inadmissible in court. Review: Rules of Evidence.","is_correct":false},{"text":"Circumstantial evidence excluded","isCorrect":false,"rationale":"'Circumstantial evidence excluded' is incorrect. The correct answer is 'Evidence from illegal search is inadmissible'. Evidence obtained as a result of an illegal search or seizure is inadmissible in court. Review: Rules of Evidence.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Evidence from illegal search is inadmissible","isCorrect":true,"rationale":"Evidence obtained as a result of an illegal search or seizure is inadmissible in court.","is_correct":true},{"text":"Evidence from illegal search is admissible","is_correct":false,"rationale":"Reversed: illegally obtained evidence and its fruits are inadmissible."},{"text":"Hearsay evidence is inadmissible in all cases","is_correct":false,"rationale":"That is the hearsay rule, which has exceptions; it is not the fruit of the poisonous tree."},{"text":"Circumstantial evidence cannot convict alone","is_correct":false,"rationale":"False: circumstantial evidence can convict (Rule 133, Sec. 4); and it is not this doctrine."}]$opt$::jsonb),
  ('cj_102', $opt$[{"text":"Acts of others not binding on accused","isCorrect":true,"rationale":"Res inter alios acta means the acts of third parties are not admissible against the accused.","is_correct":true},{"text":"All acts are admissible","isCorrect":false,"rationale":"'All acts are admissible' is incorrect. The correct answer is 'Acts of others not binding on accused'. Res inter alios acta means the acts of third parties are not admissible against the accused. Review: Rules of Evidence.","is_correct":false},{"text":"No exclusionary rule","isCorrect":false,"rationale":"'No exclusionary rule' is incorrect. The correct answer is 'Acts of others not binding on accused'. Res inter alios acta means the acts of third parties are not admissible against the accused. Review: Rules of Evidence.","is_correct":false},{"text":"Only confessions matter","isCorrect":false,"rationale":"'Only confessions matter' is incorrect. The correct answer is 'Acts of others not binding on accused'. Res inter alios acta means the acts of third parties are not admissible against the accused. Review: Rules of Evidence.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Acts of others not binding on accused","isCorrect":true,"rationale":"Res inter alios acta means the acts of third parties are not admissible against the accused.","is_correct":true},{"text":"Admissions of a party bind that party","is_correct":false,"rationale":"That is the rule on admissions, not res inter alios acta."},{"text":"Acts of a conspirator bind all co-conspirators","is_correct":false,"rationale":"That is the co-conspirator exception, the opposite effect."},{"text":"Silence of the accused is an admission","is_correct":false,"rationale":"That is admission by silence, a different rule."}]$opt$::jsonb),
  ('cj_103', $opt$[{"text":"Statement by person believing death imminent","isCorrect":true,"rationale":"A dying declaration is admissible if made by a person who believes death is imminent regarding its cause.","is_correct":true},{"text":"Any deathbed statement","isCorrect":false,"rationale":"'Any deathbed statement' is incorrect. The correct answer is 'Statement by person believing death imminent'. A dying declaration is admissible if made by a person who believes death is imminent regarding its cause. Review: Rules of Evidence.","is_correct":false},{"text":"Written will only","isCorrect":false,"rationale":"'Written will only' is incorrect. The correct answer is 'Statement by person believing death imminent'. A dying declaration is admissible if made by a person who believes death is imminent regarding its cause. Review: Rules of Evidence.","is_correct":false},{"text":"No exception exists","isCorrect":false,"rationale":"'No exception exists' is incorrect. The correct answer is 'Statement by person believing death imminent'. A dying declaration is admissible if made by a person who believes death is imminent regarding its cause. Review: Rules of Evidence.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Statement by person believing death imminent","isCorrect":true,"rationale":"A dying declaration is admissible if made by a person who believes death is imminent regarding its cause.","is_correct":true},{"text":"Statement made right after a startling event","is_correct":false,"rationale":"That is part of the res gestae (a spontaneous statement)."},{"text":"Statement against the declarant's own interest","is_correct":false,"rationale":"That is a declaration against interest."},{"text":"Statement made in a last will and testament","is_correct":false,"rationale":"A will is not a dying declaration."}]$opt$::jsonb),
