  ('crim_theory_128', $opt$[{"text":"Attachment, Commitment, Involvement, Belief","isCorrect":true,"rationale":"Hirschi identified four bonds: Attachment, Commitment, Involvement, and Belief.","is_correct":true},{"text":"Family, School, Work, Religion","isCorrect":false,"rationale":"'Family, School, Work, Religion' is incorrect. The correct answer is 'Attachment, Commitment, Involvement, Belief'. Hirschi identified four bonds: Attachment, Commitment, Involvement, and Belief. Review: Theories of Crime Causation.","is_correct":false},{"text":"Love, Fear, Respect, Trust","isCorrect":false,"rationale":"'Love, Fear, Respect, Trust' is incorrect. The correct answer is 'Attachment, Commitment, Involvement, Belief'. Hirschi identified four bonds: Attachment, Commitment, Involvement, and Belief. Review: Theories of Crime Causation.","is_correct":false},{"text":"Money, Power, Status, Fame","isCorrect":false,"rationale":"'Money, Power, Status, Fame' is incorrect. The correct answer is 'Attachment, Commitment, Involvement, Belief'. Hirschi identified four bonds: Attachment, Commitment, Involvement, and Belief. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Attachment, Commitment, Involvement, Belief","isCorrect":true,"rationale":"Hirschi identified four bonds: Attachment, Commitment, Involvement, and Belief.","is_correct":true},{"text":"Attachment, Commitment, Opportunity, Belief","is_correct":false,"rationale":"'Opportunity' is not one of Hirschi's bonds; the third bond is involvement."},{"text":"Attachment, Conformity, Involvement, Belief","is_correct":false,"rationale":"'Conformity' is not one of Hirschi's bonds; the second bond is commitment."},{"text":"Supervision, Commitment, Involvement, Values","is_correct":false,"rationale":"Hirschi's four bonds are attachment, commitment, involvement and belief."}]$opt$::jsonb),
