  ('crm_055', $opt$[{"text":"Crime needs target, offender, no guardian","isCorrect":true,"rationale":"Routine Activities Theory states crime occurs with a motivated offender, suitable target, and lack of guardian.","is_correct":true},{"text":"Crime is random","isCorrect":false,"rationale":"'Crime is random' is incorrect. The correct answer is 'Crime needs target, offender, no guardian'. Routine Activities Theory states crime occurs with a motivated offender, suitable target, and lack of guardian. Review: Theories of Crime Causation.","is_correct":false},{"text":"Crime is planned","isCorrect":false,"rationale":"'Crime is planned' is incorrect. The correct answer is 'Crime needs target, offender, no guardian'. Routine Activities Theory states crime occurs with a motivated offender, suitable target, and lack of guardian. Review: Theories of Crime Causation.","is_correct":false},{"text":"Crime needs motive only","isCorrect":false,"rationale":"'Crime needs motive only' is incorrect. The correct answer is 'Crime needs target, offender, no guardian'. Routine Activities Theory states crime occurs with a motivated offender, suitable target, and lack of guardian. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Crime needs target, offender, no guardian","isCorrect":true,"rationale":"Routine Activities Theory states crime occurs with a motivated offender, suitable target, and lack of guardian.","is_correct":true},{"text":"Crime needs motive, means, opportunity","is_correct":false,"rationale":"Those are investigative concepts, not the three elements of routine activity theory."},{"text":"Crime needs weak bonds, strain, peers","is_correct":false,"rationale":"That mixes other theories; routine activity names a target, an offender and no capable guardian."},{"text":"Crime needs a victim, a law, a penalty","is_correct":false,"rationale":"Those relate to the legal definition of crime, not routine activity theory."}]$opt$::jsonb),
  ('crm_066', $opt$[{"text":"Criminals weigh costs and benefits","isCorrect":true,"rationale":"Rational Choice Theory suggests criminals rationally weigh the costs and benefits before offending.","is_correct":true},{"text":"Crime is random","isCorrect":false,"rationale":"'Crime is random' is incorrect. The correct answer is 'Criminals weigh costs and benefits'. Rational Choice Theory suggests criminals rationally weigh the costs and benefits before offending. Review: Theories of Crime Causation.","is_correct":false},{"text":"Crime is biological","isCorrect":false,"rationale":"'Crime is biological' is incorrect. The correct answer is 'Criminals weigh costs and benefits'. Rational Choice Theory suggests criminals rationally weigh the costs and benefits before offending. Review: Theories of Crime Causation.","is_correct":false},{"text":"Crime is uncontrollable","isCorrect":false,"rationale":"'Crime is uncontrollable' is incorrect. The correct answer is 'Criminals weigh costs and benefits'. Rational Choice Theory suggests criminals rationally weigh the costs and benefits before offending. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Criminals weigh costs and benefits","isCorrect":true,"rationale":"Rational Choice Theory suggests criminals rationally weigh the costs and benefits before offending.","is_correct":true},{"text":"Criminals learn crime from peers","is_correct":false,"rationale":"That is differential association."},{"text":"Criminals lack self-control from childhood","is_correct":false,"rationale":"That is the general theory of crime (Gottfredson and Hirschi)."},{"text":"Criminals respond to blocked goals","is_correct":false,"rationale":"That is strain theory."}]$opt$::jsonb),
  ('crm_067', $opt$[{"text":"Low self-control causes crime","isCorrect":true,"rationale":"Gottfredson and Hirschi's General Theory states that low self-control is the main cause of crime.","is_correct":true},{"text":"High intelligence causes crime","isCorrect":false,"rationale":"'High intelligence causes crime' is incorrect. The correct answer is 'Low self-control causes crime'. Gottfredson and Hirschi's General Theory states that low self-control is the main cause of crime. Review: Theories of Crime Causation.","is_correct":false},{"text":"Poverty alone causes crime","isCorrect":false,"rationale":"'Poverty alone causes crime' is incorrect. The correct answer is 'Low self-control causes crime'. Gottfredson and Hirschi's General Theory states that low self-control is the main cause of crime. Review: Theories of Crime Causation.","is_correct":false},{"text":"Crime is genetic only","isCorrect":false,"rationale":"'Crime is genetic only' is incorrect. The correct answer is 'Low self-control causes crime'. Gottfredson and Hirschi's General Theory states that low self-control is the main cause of crime. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Low self-control causes crime","isCorrect":true,"rationale":"Gottfredson and Hirschi's General Theory states that low self-control is the main cause of crime.","is_correct":true},{"text":"Weak social bonds cause crime","is_correct":false,"rationale":"That is Hirschi's earlier social bond theory; the general theory points to low self-control."},{"text":"Blocked opportunities cause crime","is_correct":false,"rationale":"That is strain theory."},{"text":"Learned definitions cause crime","is_correct":false,"rationale":"That is differential association."}]$opt$::jsonb),
  ('crm_068', $opt$[{"text":"Offenders rationalize their behavior","isCorrect":true,"rationale":"Neutralization Theory explains how offenders justify or rationalize their criminal behavior.","is_correct":true},{"text":"No rationalization needed","isCorrect":false,"rationale":"'No rationalization needed' is incorrect. The correct answer is 'Offenders rationalize their behavior'. Neutralization Theory explains how offenders justify or rationalize their criminal behavior. Review: Theories of Crime Causation.","is_correct":false},{"text":"Crime is always justified","isCorrect":false,"rationale":"'Crime is always justified' is incorrect. The correct answer is 'Offenders rationalize their behavior'. Neutralization Theory explains how offenders justify or rationalize their criminal behavior. Review: Theories of Crime Causation.","is_correct":false},{"text":"Crime cannot be rationalized","isCorrect":false,"rationale":"'Crime cannot be rationalized' is incorrect. The correct answer is 'Offenders rationalize their behavior'. Neutralization Theory explains how offenders justify or rationalize their criminal behavior. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Offenders rationalize their behavior","isCorrect":true,"rationale":"Neutralization Theory explains how offenders justify or rationalize their criminal behavior.","is_correct":true},{"text":"Offenders imitate admired role models","is_correct":false,"rationale":"That is social learning through imitation."},{"text":"Offenders lack attachment to parents","is_correct":false,"rationale":"That is social bond theory."},{"text":"Offenders act on impulse without thought","is_correct":false,"rationale":"That is low self-control, not neutralization."}]$opt$::jsonb),
  ('crm_075', $opt$[{"text":"Crime varies across life stages","isCorrect":true,"rationale":"Life Course Theory examines how criminal behavior changes throughout a person's life.","is_correct":true},{"text":"Crime is constant","isCorrect":false,"rationale":"'Crime is constant' is incorrect. The correct answer is 'Crime varies across life stages'. Life Course Theory examines how criminal behavior changes throughout a person's life. Review: Theories of Crime Causation.","is_correct":false},{"text":"Only youth commit crime","isCorrect":false,"rationale":"'Only youth commit crime' is incorrect. The correct answer is 'Crime varies across life stages'. Life Course Theory examines how criminal behavior changes throughout a person's life. Review: Theories of Crime Causation.","is_correct":false},{"text":"Only elderly commit crime","isCorrect":false,"rationale":"'Only elderly commit crime' is incorrect. The correct answer is 'Crime varies across life stages'. Life Course Theory examines how criminal behavior changes throughout a person's life. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Crime varies across life stages","isCorrect":true,"rationale":"Life Course Theory examines how criminal behavior changes throughout a person's life.","is_correct":true},{"text":"Crime follows one fixed path from birth","is_correct":false,"rationale":"Life course theory stresses change and turning points, not a fixed path."},{"text":"Crime is caused by inherited traits","is_correct":false,"rationale":"That is a biological (positivist) view."},{"text":"Crime is learned in delinquent gangs","is_correct":false,"rationale":"That is subcultural or differential association theory."}]$opt$::jsonb),
  ('crm_097', $opt$[{"text":"Interaction of biology and environment in crime","isCorrect":true,"rationale":"Biosocial criminology examines how biology and environment interact.","is_correct":true},{"text":"Biology only","isCorrect":false,"rationale":"'Biology only' is incorrect. The correct answer is 'Interaction of biology and environment in crime'. Biosocial criminology examines how biology and environment interact. Review: Theories of Crime Causation.","is_correct":false},{"text":"Environment only","isCorrect":false,"rationale":"'Environment only' is incorrect. The correct answer is 'Interaction of biology and environment in crime'. Biosocial criminology examines how biology and environment interact. Review: Theories of Crime Causation.","is_correct":false},{"text":"Neither factor","isCorrect":false,"rationale":"'Neither factor' is incorrect. The correct answer is 'Interaction of biology and environment in crime'. Biosocial criminology examines how biology and environment interact. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Interaction of biology and environment in crime","isCorrect":true,"rationale":"Biosocial criminology examines how biology and environment interact.","is_correct":true},{"text":"Biology alone as the cause of crime","is_correct":false,"rationale":"Biosocial criminology combines biology with environment; biology alone is older biological positivism."},{"text":"Environment alone as the cause of crime","is_correct":false,"rationale":"That leaves out the biological side that biosocial criminology adds."},{"text":"Physical features that mark born criminals","is_correct":false,"rationale":"That is Lombroso's atavism theory."}]$opt$::jsonb),
  ('crm_098', $opt$[{"text":"Study of criminal career development","isCorrect":true,"rationale":"Developmental criminology studies how criminal behavior develops over life course.","is_correct":true},{"text":"Child development only","isCorrect":false,"rationale":"'Child development only' is incorrect. The correct answer is 'Study of criminal career development'. Developmental criminology studies how criminal behavior develops over life course. Review: Theories of Crime Causation.","is_correct":false},{"text":"Adult crime only","isCorrect":false,"rationale":"'Adult crime only' is incorrect. The correct answer is 'Study of criminal career development'. Developmental criminology studies how criminal behavior develops over life course. Review: Theories of Crime Causation.","is_correct":false},{"text":"Elderly crime","isCorrect":false,"rationale":"'Elderly crime' is incorrect. The correct answer is 'Study of criminal career development'. Developmental criminology studies how criminal behavior develops over life course. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Study of criminal career development","isCorrect":true,"rationale":"Developmental criminology studies how criminal behavior develops over life course.","is_correct":true},{"text":"Study of children's normal growth stages","is_correct":false,"rationale":"That is developmental psychology, not developmental criminology."},{"text":"Study of crime by social class","is_correct":false,"rationale":"That is a structural approach."},{"text":"Study of crime rates across countries","is_correct":false,"rationale":"That is comparative criminology."}]$opt$::jsonb),
  ('crm_099', $opt$[{"text":"Study of gender and crime","isCorrect":true,"rationale":"Feminist criminology examines how gender affects crime and justice.","is_correct":true},{"text":"Male crime only","isCorrect":false,"rationale":"'Male crime only' is incorrect. The correct answer is 'Study of gender and crime'. Feminist criminology examines how gender affects crime and justice. Review: Theories of Crime Causation.","is_correct":false},{"text":"Female crime only","isCorrect":false,"rationale":"'Female crime only' is incorrect. The correct answer is 'Study of gender and crime'. Feminist criminology examines how gender affects crime and justice. Review: Theories of Crime Causation.","is_correct":false},{"text":"Ignores gender","isCorrect":false,"rationale":"'Ignores gender' is incorrect. The correct answer is 'Study of gender and crime'. Feminist criminology examines how gender affects crime and justice. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Study of gender and crime","isCorrect":true,"rationale":"Feminist criminology examines how gender affects crime and justice.","is_correct":true},{"text":"Study of crime by men only","is_correct":false,"rationale":"Feminist criminology examines gender, including women's experiences that older theories ignored."},{"text":"Study of crime by social class","is_correct":false,"rationale":"That is critical (Marxist) criminology."},{"text":"Study of crime in families","is_correct":false,"rationale":"Family violence is one topic, but the perspective is about gender."}]$opt$::jsonb),
  ('crm_100', $opt$[{"text":"Examines power structures and crime","isCorrect":true,"rationale":"Critical criminology examines how power structures create crime and criminals.","is_correct":true},{"text":"Accepts status quo","isCorrect":false,"rationale":"'Accepts status quo' is incorrect. The correct answer is 'Examines power structures and crime'. Critical criminology examines how power structures create crime and criminals. Review: Theories of Crime Causation.","is_correct":false},{"text":"Individual focus only","isCorrect":false,"rationale":"'Individual focus only' is incorrect. The correct answer is 'Examines power structures and crime'. Critical criminology examines how power structures create crime and criminals. Review: Theories of Crime Causation.","is_correct":false},{"text":"No political analysis","isCorrect":false,"rationale":"'No political analysis' is incorrect. The correct answer is 'Examines power structures and crime'. Critical criminology examines how power structures create crime and criminals. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Examines power structures and crime","isCorrect":true,"rationale":"Critical criminology examines how power structures create crime and criminals.","is_correct":true},{"text":"Examines individual traits and crime","is_correct":false,"rationale":"That is an individual-level (positivist) approach."},{"text":"Examines brain chemistry and crime","is_correct":false,"rationale":"That is biological criminology."},{"text":"Examines police efficiency and crime","is_correct":false,"rationale":"That is administrative criminology."}]$opt$::jsonb),
  ('crm_101', $opt$[{"text":"Non-violent response to crime","isCorrect":true,"rationale":"Peacemaking criminology advocates non-violent, compassionate responses.","is_correct":true},{"text":"Harsh punishment","isCorrect":false,"rationale":"'Harsh punishment' is incorrect. The correct answer is 'Non-violent response to crime'. Peacemaking criminology advocates non-violent, compassionate responses. Review: Theories of Crime Causation.","is_correct":false},{"text":"War on crime","isCorrect":false,"rationale":"'War on crime' is incorrect. The correct answer is 'Non-violent response to crime'. Peacemaking criminology advocates non-violent, compassionate responses. Review: Theories of Crime Causation.","is_correct":false},{"text":"Zero tolerance","isCorrect":false,"rationale":"'Zero tolerance' is incorrect. The correct answer is 'Non-violent response to crime'. Peacemaking criminology advocates non-violent, compassionate responses. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Non-violent response to crime","isCorrect":true,"rationale":"Peacemaking criminology advocates non-violent, compassionate responses.","is_correct":true},{"text":"Harsh punishment to deter crime","is_correct":false,"rationale":"That is deterrence, the opposite of peacemaking."},{"text":"Zero tolerance of minor offenses","is_correct":false,"rationale":"That is zero-tolerance policing."},{"text":"Military-style response to crime","is_correct":false,"rationale":"That is the 'war on crime' approach that peacemaking rejects."}]$opt$::jsonb),
  ('crm_104', $opt$[{"text":"Study of crime within cultural context","isCorrect":true,"rationale":"Cultural criminology examines crime within its cultural context.","is_correct":true},{"text":"Ignores culture","isCorrect":false,"rationale":"'Ignores culture' is incorrect. The correct answer is 'Study of crime within cultural context'. Cultural criminology examines crime within its cultural context. Review: Theories of Crime Causation.","is_correct":false},{"text":"Law only","isCorrect":false,"rationale":"'Law only' is incorrect. The correct answer is 'Study of crime within cultural context'. Cultural criminology examines crime within its cultural context. Review: Theories of Crime Causation.","is_correct":false},{"text":"Biology only","isCorrect":false,"rationale":"'Biology only' is incorrect. The correct answer is 'Study of crime within cultural context'. Cultural criminology examines crime within its cultural context. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Study of crime within cultural context","isCorrect":true,"rationale":"Cultural criminology examines crime within its cultural context.","is_correct":true},{"text":"Study of crime within the legal code","is_correct":false,"rationale":"That is criminal law."},{"text":"Study of crime within brain functions","is_correct":false,"rationale":"That is biological criminology."},{"text":"Study of crime within prison walls","is_correct":false,"rationale":"That is penology."}]$opt$::jsonb),
  ('crm_105', $opt$[{"text":"Economic dominance weakens social institutions","isCorrect":true,"rationale":"Institutional anomie theory links crime to economic institutions dominance.","is_correct":true},{"text":"Strong institutions","isCorrect":false,"rationale":"'Strong institutions' is incorrect. The correct answer is 'Economic dominance weakens social institutions'. Institutional anomie theory links crime to economic institutions dominance. Review: Theories of Crime Causation.","is_correct":false},{"text":"No anomie","isCorrect":false,"rationale":"'No anomie' is incorrect. The correct answer is 'Economic dominance weakens social institutions'. Institutional anomie theory links crime to economic institutions dominance. Review: Theories of Crime Causation.","is_correct":false},{"text":"Individual anomie","isCorrect":false,"rationale":"'Individual anomie' is incorrect. The correct answer is 'Economic dominance weakens social institutions'. Institutional anomie theory links crime to economic institutions dominance. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Economic dominance weakens social institutions","isCorrect":true,"rationale":"Institutional anomie theory links crime to economic institutions dominance.","is_correct":true},{"text":"Weak family bonds weaken economic institutions","is_correct":false,"rationale":"Reversed: Messner and Rosenfeld say the economy dominates and weakens family, school and polity."},{"text":"Strong institutions produce normlessness","is_correct":false,"rationale":"Strong non-economic institutions restrain anomie; they do not produce it."},{"text":"Individual strain from failing exams","is_correct":false,"rationale":"That is strain at the individual level, not institutional anomie."}]$opt$::jsonb),
  ('crm_107', $opt$[{"text":"Crime peaks in late teens then declines","isCorrect":true,"rationale":"The age-crime curve shows crime peaks around age 17-19 then declines.","is_correct":true},{"text":"Constant crime rate","isCorrect":false,"rationale":"'Constant crime rate' is incorrect. The correct answer is 'Crime peaks in late teens then declines'. The age-crime curve shows crime peaks around age 17-19 then declines. Review: Theories of Crime Causation.","is_correct":false},{"text":"Increases with age","isCorrect":false,"rationale":"'Increases with age' is incorrect. The correct answer is 'Crime peaks in late teens then declines'. The age-crime curve shows crime peaks around age 17-19 then declines. Review: Theories of Crime Causation.","is_correct":false},{"text":"No pattern","isCorrect":false,"rationale":"'No pattern' is incorrect. The correct answer is 'Crime peaks in late teens then declines'. The age-crime curve shows crime peaks around age 17-19 then declines. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Crime peaks in late teens then declines","isCorrect":true,"rationale":"The age-crime curve shows crime peaks around age 17-19 then declines.","is_correct":true},{"text":"Crime peaks in middle age then declines","is_correct":false,"rationale":"The peak is in the late teens to early twenties, not middle age."},{"text":"Crime rises steadily throughout life","is_correct":false,"rationale":"Most offending falls after early adulthood."},{"text":"Crime is the same at every age","is_correct":false,"rationale":"Crime varies sharply with age."}]$opt$::jsonb),
  ('crm_109', $opt$[{"text":"Research by former prisoners","isCorrect":true,"rationale":"Convict criminology involves research conducted by former prisoners.","is_correct":true},{"text":"Traditional research","isCorrect":false,"rationale":"'Traditional research' is incorrect. The correct answer is 'Research by former prisoners'. Convict criminology involves research conducted by former prisoners. Review: Theories of Crime Causation.","is_correct":false},{"text":"Police research","isCorrect":false,"rationale":"'Police research' is incorrect. The correct answer is 'Research by former prisoners'. Convict criminology involves research conducted by former prisoners. Review: Theories of Crime Causation.","is_correct":false},{"text":"Court research","isCorrect":false,"rationale":"'Court research' is incorrect. The correct answer is 'Research by former prisoners'. Convict criminology involves research conducted by former prisoners. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Research by former prisoners","isCorrect":true,"rationale":"Convict criminology involves research conducted by former prisoners.","is_correct":true},{"text":"Research by prison officials","is_correct":false,"rationale":"Convict criminology is research led by people who were imprisoned."},{"text":"Research on prison architecture","is_correct":false,"rationale":"That is a penology topic."},{"text":"Research by crime victims","is_correct":false,"rationale":"That is victim-led research, not convict criminology."}]$opt$::jsonb),
  ('crm_110', $opt$[{"text":"Combining multiple theories to explain crime","isCorrect":true,"rationale":"Integrated theories combine elements from multiple criminological theories.","is_correct":true},{"text":"Single theory","isCorrect":false,"rationale":"'Single theory' is incorrect. The correct answer is 'Combining multiple theories to explain crime'. Integrated theories combine elements from multiple criminological theories. Review: Theories of Crime Causation.","is_correct":false},{"text":"No theory","isCorrect":false,"rationale":"'No theory' is incorrect. The correct answer is 'Combining multiple theories to explain crime'. Integrated theories combine elements from multiple criminological theories. Review: Theories of Crime Causation.","is_correct":false},{"text":"Rejecting theory","isCorrect":false,"rationale":"'Rejecting theory' is incorrect. The correct answer is 'Combining multiple theories to explain crime'. Integrated theories combine elements from multiple criminological theories. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Combining multiple theories to explain crime","isCorrect":true,"rationale":"Integrated theories combine elements from multiple criminological theories.","is_correct":true},{"text":"Testing one theory against all the others","is_correct":false,"rationale":"That is theory competition, not integration."},{"text":"Applying one theory to every type of crime","is_correct":false,"rationale":"That is a general theory, not an integrated one."},{"text":"Rejecting theory in favor of statistics","is_correct":false,"rationale":"That is atheoretical research."}]$opt$::jsonb),
  ('crm_112', $opt$[{"text":"Community willingness to intervene","isCorrect":true,"rationale":"Collective efficacy is community willingness to intervene for common good.","is_correct":true},{"text":"Individual action","isCorrect":false,"rationale":"'Individual action' is incorrect. The correct answer is 'Community willingness to intervene'. Collective efficacy is community willingness to intervene for common good. Review: Theories of Crime Causation.","is_correct":false},{"text":"Police action","isCorrect":false,"rationale":"'Police action' is incorrect. The correct answer is 'Community willingness to intervene'. Collective efficacy is community willingness to intervene for common good. Review: Theories of Crime Causation.","is_correct":false},{"text":"Court action","isCorrect":false,"rationale":"'Court action' is incorrect. The correct answer is 'Community willingness to intervene'. Collective efficacy is community willingness to intervene for common good. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Community willingness to intervene","isCorrect":true,"rationale":"Collective efficacy is community willingness to intervene for common good.","is_correct":true},{"text":"Police willingness to intervene","is_correct":false,"rationale":"Collective efficacy is about residents, not the police."},{"text":"Community wealth and property values","is_correct":false,"rationale":"Wealth may relate, but collective efficacy is social cohesion plus willingness to act."},{"text":"Individual willingness to report","is_correct":false,"rationale":"It is shared trust and action among residents, not one person."}]$opt$::jsonb),
  ('crm_114', $opt$[{"text":"Process of stopping criminal behavior","isCorrect":true,"rationale":"Desistance theory studies how and why people stop offending.","is_correct":true},{"text":"Starting crime","isCorrect":false,"rationale":"'Starting crime' is incorrect. The correct answer is 'Process of stopping criminal behavior'. Desistance theory studies how and why people stop offending. Review: Theories of Crime Causation.","is_correct":false},{"text":"Continuing crime","isCorrect":false,"rationale":"'Continuing crime' is incorrect. The correct answer is 'Process of stopping criminal behavior'. Desistance theory studies how and why people stop offending. Review: Theories of Crime Causation.","is_correct":false},{"text":"Escalating crime","isCorrect":false,"rationale":"'Escalating crime' is incorrect. The correct answer is 'Process of stopping criminal behavior'. Desistance theory studies how and why people stop offending. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Process of stopping criminal behavior","isCorrect":true,"rationale":"Desistance theory studies how and why people stop offending.","is_correct":true},{"text":"Process of starting criminal behavior","is_correct":false,"rationale":"That is onset, the beginning of offending, not desistance."},{"text":"Process of escalating criminal behavior","is_correct":false,"rationale":"That is escalation, moving to more serious offending."},{"text":"Process of repeating criminal behavior","is_correct":false,"rationale":"That is persistence, or recidivism."}]$opt$::jsonb),
  ('crm_116', $opt$[{"text":"Abused children becoming abusers","isCorrect":true,"rationale":"The cycle of violence suggests abuse victims may become abusers.","is_correct":true},{"text":"Random violence","isCorrect":false,"rationale":"'Random violence' is incorrect. The correct answer is 'Abused children becoming abusers'. The cycle of violence suggests abuse victims may become abusers. Review: Theories of Crime Causation.","is_correct":false},{"text":"No pattern","isCorrect":false,"rationale":"'No pattern' is incorrect. The correct answer is 'Abused children becoming abusers'. The cycle of violence suggests abuse victims may become abusers. Review: Theories of Crime Causation.","is_correct":false},{"text":"One-time event","isCorrect":false,"rationale":"'One-time event' is incorrect. The correct answer is 'Abused children becoming abusers'. The cycle of violence suggests abuse victims may become abusers. Review: Theories of Crime Causation.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Abused children becoming abusers","isCorrect":true,"rationale":"The cycle of violence suggests abuse victims may become abusers.","is_correct":true},{"text":"Abusers becoming victims later in life","is_correct":false,"rationale":"Reversed: the cycle runs from abused child to later abuser."},{"text":"Violence spreading through the media","is_correct":false,"rationale":"That is media contagion."},{"text":"Retaliation between rival gangs","is_correct":false,"rationale":"That is gang retaliation."}]$opt$::jsonb),
