  ('lea_104', $opt$[{"text":"Assigning tasks and power to subordinates","isCorrect":true,"rationale":"Delegation involves assigning tasks and authority to subordinates to accomplish objectives.","is_correct":true},{"text":"Retaining all power","isCorrect":false,"rationale":"'Retaining all power' is incorrect. The correct answer is 'Assigning tasks and power to subordinates'. Delegation involves assigning tasks and authority to subordinates to accomplish objectives. Review: Police Organization and Administration.","is_correct":false},{"text":"No delegation allowed","isCorrect":false,"rationale":"'No delegation allowed' is incorrect. The correct answer is 'Assigning tasks and power to subordinates'. Delegation involves assigning tasks and authority to subordinates to accomplish objectives. Review: Police Organization and Administration.","is_correct":false},{"text":"Only to equals","isCorrect":false,"rationale":"'Only to equals' is incorrect. The correct answer is 'Assigning tasks and power to subordinates'. Delegation involves assigning tasks and authority to subordinates to accomplish objectives. Review: Police Organization and Administration.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Assigning tasks and power to subordinates","isCorrect":true,"rationale":"Delegation involves assigning tasks and authority to subordinates to accomplish objectives.","is_correct":true},{"text":"Keeping all decision power at the top","is_correct":false,"rationale":"That is centralization."},{"text":"Passing responsibility up to superiors","is_correct":false,"rationale":"With delegation, tasks and authority go down to subordinates."},{"text":"Assigning tasks to officers of equal rank","is_correct":false,"rationale":"Delegation goes to subordinates, not equals."}]$opt$::jsonb),
  ('lea_077', $opt$[{"text":"Strengths, Weaknesses, Opportunities, Threats","isCorrect":true,"rationale":"SWOT analysis evaluates Strengths, Weaknesses, Opportunities, and Threats for strategic planning.","is_correct":true},{"text":"Strategic Work On Targets","isCorrect":false,"rationale":"'Strategic Work On Targets' is incorrect. The correct answer is 'Strengths, Weaknesses, Opportunities, Threats'. SWOT analysis evaluates Strengths, Weaknesses, Opportunities, and Threats for strategic planning. Review: Police Planning.","is_correct":false},{"text":"Special Weapons Operations Team","isCorrect":false,"rationale":"'Special Weapons Operations Team' is incorrect. The correct answer is 'Strengths, Weaknesses, Opportunities, Threats'. SWOT analysis evaluates Strengths, Weaknesses, Opportunities, and Threats for strategic planning. Review: Police Planning.","is_correct":false},{"text":"Standard Work Order Template","isCorrect":false,"rationale":"'Standard Work Order Template' is incorrect. The correct answer is 'Strengths, Weaknesses, Opportunities, Threats'. SWOT analysis evaluates Strengths, Weaknesses, Opportunities, and Threats for strategic planning. Review: Police Planning.","is_correct":false}]$opt$::jsonb, $opt$[{"text":"Strengths, Weaknesses, Opportunities, Threats","isCorrect":true,"rationale":"SWOT analysis evaluates Strengths, Weaknesses, Opportunities, and Threats for strategic planning.","is_correct":true},{"text":"Strengths, Weaknesses, Operations, Targets","is_correct":false,"rationale":"The O and T in SWOT stand for Opportunities and Threats."},{"text":"Strategy, Workforce, Objectives, Timelines","is_correct":false,"rationale":"Not SWOT, which stands for Strengths, Weaknesses, Opportunities, Threats."},{"text":"Strengths, Weaknesses, Opportunities, Tactics","is_correct":false,"rationale":"The T in SWOT is Threats, not Tactics."}]$opt$::jsonb),
